(9, 1, '2026-04-28 18:58:40', '2026-04-28 18:58:40', '<!-- wp:paragraph -->\n<p>Welcome to WordPress! This is your first post. Edit or delete it to take the first step in your blogging journey.</p>\n<!-- /wp:paragraph -->', 'Hello World!', '', 'trash', 'open', 'open', '', 'hello-world__trashed', '', '', '2026-04-28 18:58:40', '2026-04-28 18:58:40', '', 0, 'https://onlinekomunikacija.wordpress.com/2026/04/28/hello-world/', 0, 'post', '', 0),
(15, 1, '2026-04-28 21:36:19', '2026-04-28 19:36:19', '<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\"><!-- wp:group {\"metadata\":{\"name\":\"About\"},\"align\":\"wide\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}},\"border\":{\"radius\":\"16px\"},\"background\":{\"backgroundSize\":\"contain\",\"backgroundRepeat\":\"no-repeat\",\"backgroundPosition\":\"45% 0%\"}},\"backgroundColor\":\"base\",\"fontSize\":\"small\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide has-base-background-color has-background has-small-font-size\" style=\"border-radius:16px;padding-top:var(--wp--preset--spacing--40);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--40);padding-left:var(--wp--preset--spacing--40)\"><!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":\"1.5rem\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"stretch\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:group {\"align\":\"wide\",\"style\":{\"typography\":{\"textTransform\":\"none\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|primary\"}}}},\"textColor\":\"primary\",\"fontSize\":\"small\",\"fontFamily\":\"inter-tight\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"stretch\"}} -->\n<div class=\"wp-block-group alignwide has-primary-color has-text-color has-link-color has-inter-tight-font-family has-small-font-size\" style=\"text-transform:none\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Za samo pet godina, više od milijardu novih korisnika priključilo se globalnoj digitalnoj mreži. Danas internet koristi 5,56 milijardi ljudi – više nego što gleda televiziju.</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"var:preset|spacing|10\"} -->\n<div style=\"height:var(--wp--preset--spacing--10)\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Stats\"},\"align\":\"wide\",\"className\":\"statistike-grid\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide statistike-grid\" style=\"padding-right:0;padding-left:0\"><!-- wp:columns {\"metadata\":{\"name\":\"Stats\"},\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"className\":\"stat-card\"} -->\n<div class=\"wp-block-column stat-card\"><!-- wp:heading {\"level\":3,\"className\":\"stat-number\",\"style\":{\"typography\":{\"textAlign\":\"center\"},\"color\":{\"text\":\"#185fa5\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#185fa5\"}}}},\"fontSize\":\"x-large\"} -->\n<h3 class=\"wp-block-heading has-text-align-center stat-number has-text-color has-link-color has-x-large-font-size\" style=\"color:#185fa5\">5,5+ mlrd</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"stat-label\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center stat-label\">korisnika interneta globalno</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"stat-card\"} -->\n<div class=\"wp-block-column stat-card\"><!-- wp:heading {\"level\":3,\"className\":\"stat-number\",\"style\":{\"typography\":{\"textAlign\":\"center\"},\"color\":{\"text\":\"#185fa5\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#185fa5\"}}}},\"fontSize\":\"x-large\"} -->\n<h3 class=\"wp-block-heading has-text-align-center stat-number has-text-color has-link-color has-x-large-font-size\" style=\"color:#185fa5\">4,6+ milijardi</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"stat-label\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center stat-label\">korisnika društvenih mreža</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"stat-card\"} -->\n<div class=\"wp-block-column stat-card\"><!-- wp:heading {\"level\":3,\"className\":\"stat-number\",\"style\":{\"typography\":{\"textAlign\":\"center\"},\"color\":{\"text\":\"#185fa5\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#185fa5\"}}}},\"fontSize\":\"x-large\"} -->\n<h3 class=\"wp-block-heading has-text-align-center stat-number has-text-color has-link-color has-x-large-font-size\" style=\"color:#185fa5\">6h 30+ min</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"stat-label\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center stat-label\">prosječno dnevno online</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"stat-card\"} -->\n<div class=\"wp-block-column stat-card\"><!-- wp:heading {\"level\":3,\"className\":\"stat-number\",\"style\":{\"typography\":{\"textAlign\":\"center\"},\"color\":{\"text\":\"#185fa5\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#185fa5\"}}}},\"fontSize\":\"x-large\"} -->\n<h3 class=\"wp-block-heading has-text-align-center stat-number has-text-color has-link-color has-x-large-font-size\" style=\"color:#185fa5\">+1 mlrd</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"stat-label\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center stat-label\">novih korisnika od 2020.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"categories\":[\"banner\"],\"patternName\":\"twentytwentyfour/cta-content-image-on-right\",\"name\":\"Event details\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}},\"heading\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"backgroundColor\":\"accent-5\",\"textColor\":\"contrast\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-contrast-color has-accent-5-background-color has-text-color has-background has-link-color\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\"><!-- wp:columns {\"verticalAlignment\":\"center\",\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\"}}}} -->\n<div class=\"wp-block-columns alignwide are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:50%\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\"><strong><em>Kako stoji Bosna i Hercegovina?</em></strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"fontSize\":\"small\"} -->\n<p class=\"has-small-font-size\"><em>BiH bilježi 86,7% penetraciju interneta sa 2,73 miliona korisnika. U posljednjih godinu dana broj korisnika porastao je za 3,2%, što pokazuje da digitalizacija ubrzano napreduje i u našoj zemlji.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"is-style-fill\"} -->\n<div class=\"wp-block-button is-style-fill\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/mywordpress/bih-kontekst/\">Istraži BiH statistiku</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:50%\"><!-- wp:image {\"id\":78,\"aspectRatio\":\"4/3\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-default\",\"style\":{\"color\":{\"duotone\":\"unset\"}}} -->\n<figure class=\"wp-block-image size-full is-style-default\"><img src=\"http://localhost/mywordpress/wp-content/uploads/2026/05/yogas-design-j6qn9se4akm-unsplash.jpg\" alt=\"\" class=\"wp-image-78\" style=\"aspect-ratio:4/3;object-fit:cover\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Call to action\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\"><!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>Najpopularnije platforme u 2025. godini</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:table {\"align\":\"wide\",\"className\":\"is-style-stripes\",\"style\":{\"border\":{\"width\":\"4px\"},\"typography\":{\"fontSize\":\"1.3rem\"}},\"gradient\":\"gradient-5\"} -->\n<figure class=\"wp-block-table alignwide is-style-stripes\" style=\"font-size:1.3rem\"><table class=\"has-gradient-5-gradient-background has-background has-fixed-layout\" style=\"border-width:4px\"><thead><tr><th class=\"has-text-align-center\" data-align=\"center\">Platforma</th><th class=\"has-text-align-center\" data-align=\"center\">Broj korisnika</th><th class=\"has-text-align-center\" data-align=\"center\">Glavna grupa</th></tr></thead><tbody><tr><td class=\"has-text-align-center\" data-align=\"center\">Facebook</td><td class=\"has-text-align-center\" data-align=\"center\">3,07 milijarde</td><td class=\"has-text-align-center\" data-align=\"center\">25–45 godina</td></tr><tr><td class=\"has-text-align-center\" data-align=\"center\">YouTube</td><td class=\"has-text-align-center\" data-align=\"center\">2,50 milijarde</td><td class=\"has-text-align-center\" data-align=\"center\">Svi uzrasti</td></tr><tr><td class=\"has-text-align-center\" data-align=\"center\">Instagram</td><td class=\"has-text-align-center\" data-align=\"center\">2,00 milijarde</td><td class=\"has-text-align-center\" data-align=\"center\">18–34 godina</td></tr><tr><td class=\"has-text-align-center\" data-align=\"center\">TikTok</td><td class=\"has-text-align-center\" data-align=\"center\">1,50 milijarde</td><td class=\"has-text-align-center\" data-align=\"center\">13–24 godina</td></tr><tr><td class=\"has-text-align-center\" data-align=\"center\">WhatsApp</td><td class=\"has-text-align-center\" data-align=\"center\">2,78 milijarde</td><td class=\"has-text-align-center\" data-align=\"center\">25–45 godina</td></tr></tbody></table></figure>\n<!-- /wp:table --></div>\n<!-- /wp:group -->', 'Statistike', '', 'publish', 'closed', 'closed', '', 'statistike', '', '', '2026-06-03 17:28:06', '2026-06-03 17:28:06', '', 0, 'https://onlinekomunikacija.wordpress.com/?page_id=15', 0, 'page', '', 0),
(16, 1, '2026-04-28 21:36:10', '2026-04-28 19:36:10', '<!-- wp:group {\"metadata\":{\"categories\":[\"text\"],\"patternName\":\"twentytwentyfour/text-alternating-images\",\"name\":\"Text with alternating images\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\"><!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"className\":\"is-style-asterisk\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center is-style-asterisk\"><strong>Društvene mreže kao novi javni prostor</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null},\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>U BiH digitalne platforme nisu samo zabava - one su postale mjesto vijesti,<br>politike, dijaspore i svakodnevne komunikacije.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null},\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"var:preset|spacing|40\"} -->\n<div style=\"height:var(--wp--preset--spacing--40)\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|60\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"40%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:40%\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\"} -->\n<h3 class=\"wp-block-heading is-style-default\"><strong>Facebook dominira</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"className\":\"is-style-checkmark-list\",\"style\":{\"typography\":{\"lineHeight\":\"1.75\"}}} -->\n<ul style=\"line-height:1.75\" class=\"wp-block-list is-style-checkmark-list\"><!-- wp:list-item -->\n<li><em>Najpopularnija platforma kod 25 - 45 godina</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Glavno mjesto javne rasprave i vijesti</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Ključni kanal za dijasporu</em></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:image {\"id\":84,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"is-style-rounded\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"300px\",\"topRight\":\"300px\",\"bottomLeft\":\"300px\",\"bottomRight\":\"300px\"}}}} -->\n<figure class=\"wp-block-image size-large has-custom-border is-style-rounded\"><img src=\"http://localhost/mywordpress/wp-content/uploads/2026/05/brett-jordan-eefrxcpixna-unsplash.jpg?w=1024\" alt=\"\" class=\"wp-image-84\" style=\"border-top-left-radius:300px;border-top-right-radius:300px;border-bottom-left-radius:300px;border-bottom-right-radius:300px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"var:preset|spacing|40\"} -->\n<div style=\"height:var(--wp--preset--spacing--40)\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|60\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"width\":\"50%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:image {\"id\":85,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"is-style-rounded\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"300px\",\"topRight\":\"300px\",\"bottomLeft\":\"300px\",\"bottomRight\":\"300px\"}}}} -->\n<figure class=\"wp-block-image size-large has-custom-border is-style-rounded\"><img src=\"http://localhost/mywordpress/wp-content/uploads/2026/05/collabstr-0vk7hejwlde-unsplash.jpg?w=1024\" alt=\"\" class=\"wp-image-85\" style=\"border-top-left-radius:300px;border-top-right-radius:300px;border-bottom-left-radius:300px;border-bottom-right-radius:300px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"40%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:40%\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\"} -->\n<h3 class=\"wp-block-heading is-style-default\"><strong>TikTok i mladi</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"className\":\"is-style-checkmark-list\",\"style\":{\"typography\":{\"lineHeight\":\"1.75\"}}} -->\n<ul style=\"line-height:1.75\" class=\"wp-block-list is-style-checkmark-list\"><!-- wp:list-item -->\n<li><em>Najbrže rastuća platforma među korisnicima do 24 godine</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Novi format konzumiranja vijesti kroz kratke, viralne videe</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Lokalni kreatori sadržaja grade publiku i van granica BiH</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Platforme poput TikToka mijenjaju i jezik i kulturu mladih</em></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"categories\":[\"text\"],\"patternName\":\"twentytwentyfour/text-feature-grid-3-col\",\"name\":\"Feature grid, 3 columns\"},\"align\":\"full\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"}}},\"backgroundColor\":\"base-2\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-base-2-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"0px\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"className\":\"is-style-asterisk\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center is-style-asterisk\"><strong>Izazovi digitalnog društva</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"0px\",\"style\":{\"layout\":{\"flexSize\":\"0px\",\"selfStretch\":\"fixed\"}}} -->\n<div style=\"height:0px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Da li je BiH digitalno napredna zemlja - ili samo izgleda tako na papiru?</p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"29px\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div style=\"margin-top:0;margin-bottom:0;height:29px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Dezinformacije i lažne vijesti</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Bosanskohercegovački online prostor posebno je ranjiv na dezinformacije zbog fragmentiranog medijskog tržišta, etničkih podjela i slabe medijske regulacije. Lažne vijesti šire se najčešće putem Facebook grupa i WhatsApp poruka, često bez ikakve provjere izvora.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Digitalna pismenost</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Starije generacije i stanovnici ruralnih područja suočavaju se sa značajnim preprekama u korištenju digitalnih usluga. Osnovna pismenost nije dovoljna - potrebno je razumjeti kako funkcionišu algoritmi, prepoznati lažne vijesti i zaštititi svoje podatke.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Zaštita privatnosti</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Većina korisnika u BiH nije svjesna koliko podataka dijeli sa platformama svakodnevno. GDPR regulativa primjenjuje se i u BiH kao dio procesa evropskih integracija, ali svijest građana o pravima na privatnost ostaje zabrinjavajuće niska.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"65px\"} -->\n<div style=\"height:65px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Digitalna nejednakost</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Brzi internet nije ravnomjerno dostupan u svim dijelovima BiH. Razlika između urbanih centara poput Sarajeva, Banja Luke i Mostara i manjih mjesta i sela i dalje je izražena - kako u brzini interneta, tako i u cijeni pristupa.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Govor mržnje online</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Etničke i političke podjele koje postoje u fizičkom prostoru direktno se prenose na digitalni. Istraživanja pokazuju da je BiH jedna od zemalja regije s najvećim udjelom govora mržnje na društvenim mrežama, posebno u periodima izbora i kriza.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">E-uprava i digitalne javne usluge</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Digitalizacija državnih usluga napreduje sporije nego u susjednim zemljama. Građani još uvijek moraju fizički dolaziti po mnoge dokumente i potvrde. Ipak, neke opštine i institucije uvode online usluge, što je korak u pravom smjeru.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"></blockquote>\n<!-- /wp:quote --></div>\n<!-- /wp:group -->', 'BiH kontekst', '', 'publish', 'closed', 'closed', '', 'bih-kontekst', '', '', '2026-06-03 17:54:56', '2026-06-03 17:54:56', '', 0, 'https://onlinekomunikacija.wordpress.com/?page_id=16', 0, 'page', '', 0),
