wp--preset--spacing--10);padding-right:var(--wp--preset--spacing--10);padding-bottom:var(--wp--preset--spacing--10);padding-left:var(--wp--preset--spacing--10)\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong>O projektu</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Saznaj više o ciljevima istraživanja, metodologiji i autorima projekta.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/mywordpress/o-projektu/\">Saznaj više</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"card-box\",\"style\":{\"border\":{\"width\":\"1px\",\"color\":\"#A4A4A4\",\"radius\":{\"topLeft\":\"25px\",\"topRight\":\"25px\",\"bottomLeft\":\"25px\",\"bottomRight\":\"25px\"}},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|10\",\"right\":\"var:preset|spacing|10\"}}}} -->\n<div class=\"wp-block-column card-box has-border-color\" style=\"border-color:#A4A4A4;border-width:1px;border-top-left-radius:25px;border-top-right-radius:25px;border-bottom-left-radius:25px;border-bottom-right-radius:25px;padding-top:var(--wp--preset--spacing--10);padding-right:var(--wp--preset--spacing--10);padding-bottom:var(--wp--preset--spacing--10);padding-left:var(--wp--preset--spacing--10)\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong>BiH kontekst</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Lokalni podaci o korištenju interneta i specifičnosti digitalnog društva u BiH.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"is-style-fill\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<div class=\"wp-block-button is-style-fill\"><a class=\"wp-block-button__link has-text-align-center wp-element-button\" href=\"http://localhost/mywordpress/bih-kontekst/\">Istraži</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"card-box\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|10\",\"right\":\"var:preset|spacing|10\"}},\"border\":{\"radius\":{\"topLeft\":\"25px\",\"topRight\":\"25px\",\"bottomLeft\":\"25px\",\"bottomRight\":\"25px\"},\"width\":\"1px\"}},\"borderColor\":\"contrast-3\"} -->\n<div class=\"wp-block-column card-box has-border-color has-contrast-3-border-color\" style=\"border-width:1px;border-top-left-radius:25px;border-top-right-radius:25px;border-bottom-left-radius:25px;border-bottom-right-radius:25px;padding-top:var(--wp--preset--spacing--10);padding-right:var(--wp--preset--spacing--10);padding-bottom:var(--wp--preset--spacing--10);padding-left:var(--wp--preset--spacing--10)\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong>Zanimljivosti</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Neočekivane statistike i fascinantni fakti o internetu i društvenim mrežama.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/mywordpress/zanimljivosti/\">Otkrij</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div></div>\n<!-- /wp:cover -->', 'Početna', '', 'publish', 'closed', 'closed', '', 'pocetna', '', '', '2026-06-02 18:44:21', '2026-06-02 18:44:21', '', 0, 'https://onlinekomunikacija.wordpress.com/?page_id=39', 0, 'page', '', 0),
(43, 1, '2026-04-29 05:01:40', '2026-04-29 03:01:40', '<!-- wp:paragraph {\"align\":\"wide\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center alignwide\"><em>Ovaj sajt nastao je kao projekat na temu onlajn komunikacije i njenog uticaja na društvo. Cilj je bio da se na jednom mjestu prikupe podaco, statistike i zanimljivosti o tome kako internet i društvene mreže mijenjaju naš svakodnevni život.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>Zašto je odabrana ova tema</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\",\"verticalAlignment\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-contrast-2-color\">Tema onlajn komunikacije odabrana je jer predstavlja svakodnevnu pojavu koju koristimo gotovo nesvjesno, a njen uticaj na društvo, međuljudske odnose i mentalno zdravlje često ostaje neistražen. Cilj je bio sagledati kako društvene mreže mijenjaju način komunikacije, održavanja prijateljstava i provođenja slobodnog vremena.</mark></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-contrast-2-color\">Posebno je zanimljiv lokalni kontekst - kako ova tema izgleda u Bosni i Hercegovini u poređenju sa globalnim trendovima.</mark></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\",\"left\":\"0\",\"right\":\"0\"},\"margin\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-columns alignwide\" style=\"margin-top:var(--wp--preset--spacing--40);margin-bottom:var(--wp--preset--spacing--40);padding-top:var(--wp--preset--spacing--20);padding-right:0;padding-bottom:var(--wp--preset--spacing--20);padding-left:0\"><!-- wp:column {\"style\":{\"color\":{\"gradient\":\"linear-gradient(180deg,rgb(181,189,188) 0%,rgb(249,249,249) 100%)\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|20\",\"right\":\"var:preset|spacing|20\"},\"blockGap\":\"var:preset|spacing|10\"},\"border\":{\"width\":\"0px\",\"style\":\"none\",\"radius\":{\"topLeft\":\"35px\",\"topRight\":\"35px\",\"bottomLeft\":\"35px\",\"bottomRight\":\"35px\"}}}} -->\n<div class=\"wp-block-column has-background\" style=\"border-style:none;border-width:0px;border-top-left-radius:35px;border-top-right-radius:35px;border-bottom-left-radius:35px;border-bottom-right-radius:35px;background:linear-gradient(180deg,rgb(181,189,188) 0%,rgb(249,249,249) 100%);padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--20);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--20)\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong>Cilj projekta</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Istražiti kako onlajn komunikacija utiče na društvo i prikazati podatke na zanimljiv i pristupačan način.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|20\",\"right\":\"var:preset|spacing|20\"},\"blockGap\":\"var:preset|spacing|10\"},\"border\":{\"radius\":{\"topLeft\":\"35px\",\"topRight\":\"35px\",\"bottomLeft\":\"35px\",\"bottomRight\":\"35px\"}}},\"gradient\":\"gradient-5\"} -->\n<div class=\"wp-block-column has-gradient-5-gradient-background has-background\" style=\"border-top-left-radius:35px;border-top-right-radius:35px;border-bottom-left-radius:35px;border-bottom-right-radius:35px;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--20);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--20)\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong>Metodologija</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Podaci su prikupljeni iz izvještaja DataReportal, Statista i We Are Social, uz vlastitu anketu provedenu među korisnicima.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong> Tehnologije korištene u projektu</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:table {\"className\":\"is-style-regular\",\"style\":{\"border\":{\"width\":\"3px\"}},\"gradient\":\"gradient-5\"} -->\n<figure class=\"wp-block-table is-style-regular\"><table class=\"has-gradient-5-gradient-background has-background has-fixed-layout\" style=\"border-width:3px\"><thead><tr><th class=\"has-text-align-left\" data-align=\"left\">Tehnologije</th><th class=\"has-text-align-left\" data-align=\"left\">Svrha</th></tr></thead><tbody><tr><td class=\"has-text-align-left\" data-align=\"left\">WordPress</td><td class=\"has-text-align-left\" data-align=\"left\">Izrada i hosting glavnog sajta</td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">GitHub Pages</td><td class=\"has-text-align-left\" data-align=\"left\">Hosting interaktivne ankete</td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Google Sheets</td><td class=\"has-text-align-left\" data-align=\"left\">Baza podataka za glasove</td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Google Apps Script</td><td class=\"has-text-align-left\" data-align=\"left\">Backend za primanje i slanje podataka</td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Chart.js</td><td class=\"has-text-align-left\" data-align=\"left\">Crtanje grafikona u realnom vremenu</td></tr></tbody></table></figure>\n<!-- /wp:table -->\n\n<!-- wp:separator {\"align\":\"wide\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}}}} -->\n<hr class=\"wp-block-separator alignwide has-alpha-channel-opacity\" style=\"margin-top:var(--wp--preset--spacing--30);margin-bottom:var(--wp--preset--spacing--30)\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>Literatura i izvori</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"className\":\"is-style-default\"} -->\n<ul class=\"wp-block-list is-style-default\"><!-- wp:list-item -->\n<li><em>DataReportal (2025). Digital 2025 Global Overview Report. <a href=\"https://datareportal.com\">https://datareportal.com</a></em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>We Are Social (2025). Global Digital Report 2025. <a href=\"https://wearesocial.com\">https://wearesocial.com</a></em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Statista (2025). Social Media Statistics. <a href=\"https://statista.com\">https://statista.com</a></em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Internet World Stats (2025). Bosnia and Herzegovina Internet Usage. <a href=\"https://internetworldstats.com\">https://internetworldstats.com</a></em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Pew Research Center (2024). Social Media Use in 2024. <a href=\"https://pewresearch.org\">https://pewresearch.org</a></em></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->', 'O projektu', '', 'publish', 'closed', 'closed', '', 'o-projektu', '', '', '2026-06-03 17:57:52', '2026-06-03 17:57:52', '', 0, 'https://onlinekomunikacija.wordpress.com/?page_id=43', 0, 'page', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(44, 1, '2026-04-29 05:01:29', '2026-04-29 03:01:29', '<!-- wp:heading {\"className\":\"zanimljivosti-section-title\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center zanimljivosti-section-title\"><strong><em>Zanimljivosti o internetu u BiH</em></strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"align\":\"wide\",\"className\":\"zanimljivosti-grid\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"25px\",\"topRight\":\"25px\",\"bottomLeft\":\"25px\",\"bottomRight\":\"25px\"}}}} -->\n<div class=\"wp-block-columns alignwide zanimljivosti-grid\" style=\"border-top-left-radius:25px;border-top-right-radius:25px;border-bottom-left-radius:25px;border-bottom-right-radius:25px\"><!-- wp:column {\"className\":\"zanimljivosti-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-column zanimljivosti-card\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>BiH i dijaspora online</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\",\"className\":\"is-style-default\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity is-style-default\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Procjenjuje se da van BiH živi više od 1,3 miliona Bosanaca. Većina njih ostaje u kontaktu s domovinom isključivo putem Facebooka i WhatsAppa.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"zanimljivosti-card\"} -->\n<div class=\"wp-block-column zanimljivosti-card\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>Facebook stariji od TikToka za cijelu generaciju</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Prosječni Facebook korisnik u BiH ima između 30 i 45 godina. Prosječni TikTok korisnik ima između 16 i 24. To su bukvalno dvije različite generacije na dva različita interneta.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"zanimljivosti-card\"} -->\n<div class=\"wp-block-column zanimljivosti-card\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>Vijesti? Na Facebooku.</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Više od 60% građana BiH primarno se informiše putem društvenih mreža, a ne tradicionalnih medija. Facebook je danas važniji od večernjih vijesti.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:image {\"id\":90,\"aspectRatio\":\"16/9\",\"scale\":\"cover\",\"focalPoint\":{\"x\":0.51,\"y\":0.51},\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"75px\",\"topRight\":\"75px\",\"bottomLeft\":\"75px\",\"bottomRight\":\"75px\"}},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}}}} -->\n<figure class=\"wp-block-image size-full has-custom-border\" style=\"margin-top:var(--wp--preset--spacing--30);margin-bottom:var(--wp--preset--spacing--30)\"><img src=\"http://localhost/mywordpress/wp-content/uploads/2026/05/sumup-aqc7znjxrom-unsplash-edited.jpg\" alt=\"\" class=\"wp-image-90\" style=\"border-top-left-radius:75px;border-top-right-radius:75px;border-bottom-left-radius:75px;border-bottom-right-radius:75px;aspect-ratio:16/9;object-fit:cover;object-position:51% 51%\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"className\":\"zanimljivosti-section-title\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center zanimljivosti-section-title\"><strong><em>Globalne zanimljivosti o internetu</em></strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"align\":\"wide\",\"className\":\"zanimljivosti-grid\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"25px\",\"topRight\":\"25px\",\"bottomLeft\":\"25px\",\"bottomRight\":\"25px\"}}}} -->\n<div class=\"wp-block-columns alignwide zanimljivosti-grid\" style=\"border-top-left-radius:25px;border-top-right-radius:25px;border-bottom-left-radius:25px;border-bottom-right-radius:25px\"><!-- wp:column {\"width\":\"25%\",\"className\":\"zanimljivosti-card\"} -->\n<div class=\"wp-block-column zanimljivosti-card\" style=\"flex-basis:25%\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>Internet je mlađi nego što misliš</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>World Wide Web dostupan je javnosti tek od 1991.<br>Cijela era društvenih mreža stara je manje od 35 godina.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\",\"className\":\"zanimljivosti-card\"} -->\n<div class=\"wp-block-column zanimljivosti-card\" style=\"flex-basis:50%\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>Svake minute na internetu…</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Svake minute šalje se oko 300 miliona emailova,<br>objavljuje 500 sati YouTube videa i pošalje<br>preko 41 milion WhatsApp poruka.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"25%\",\"className\":\"zanimljivosti-card\"} -->\n<div class=\"wp-block-column zanimljivosti-card\" style=\"flex-basis:25%\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>Više od polovine čovječanstva online</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"right\"}}} -->\n<p class=\"has-text-align-right\"><em>2024 godine više od 5,4 milijarde ljudi koristilo je internet - to je oko 67% ukupne svjetske populacije. Još prije 20 godina taj broj bio je ispod 15%.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:image {\"id\":92,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"75px\",\"topRight\":\"75px\",\"bottomLeft\":\"75px\",\"bottomRight\":\"75px\"}},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}}}} -->\n<figure class=\"wp-block-image size-large has-custom-border\" style=\"margin-top:var(--wp--preset--spacing--30);margin-bottom:var(--wp--preset--spacing--30)\"><img src=\"http://localhost/mywordpress/wp-content/uploads/2026/05/firmbee-com-dfmmzzi3rmg-unsplash-edited.jpg\" alt=\"\" class=\"wp-image-92\" style=\"border-top-left-radius:75px;border-top-right-radius:75px;border-bottom-left-radius:75px;border-bottom-right-radius:75px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"className\":\"zanimljivosti-section-title\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center zanimljivosti-section-title\"><strong><em>Društvene mreže</em></strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"align\":\"wide\",\"className\":\"zanimljivosti-grid\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"25px\",\"topRight\":\"25px\",\"bottomLeft\":\"25px\",\"bottomRight\":\"25px\"}}}} -->\n<div class=\"wp-block-columns alignwide zanimljivosti-grid\" style=\"border-top-left-radius:25px;border-top-right-radius:25px;border-bottom-left-radius:25px;border-bottom-right-radius:25px\"><!-- wp:column {\"className\":\"zanimljivosti-card\"} -->\n<div class=\"wp-block-column zanimljivosti-card\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><em><strong>TikTok algoritam zna bolje od tebe</strong></em></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-medium-font-size\"><em>TikTok može predvidjeti tvoje interese nakon samo<br>nekoliko minuta gledanja. Algoritam analizira čak<br>i to koliko dugo zastaneš na određenom videu.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"zanimljivosti-card\"} -->\n<div class=\"wp-block-column zanimljivosti-card\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>Prosječan čovjek provede 6+ sati online dnevno</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-medium-font-size\"><em>Od toga gotovo 2,5 sata otpada na društvene mreže.<br>U toku jedne godine to je više od 900 sati -<br>ili cijela 37 dana neprekidnog skrolanja.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"zanimljivosti-card\"} -->\n<div class=\"wp-block-column zanimljivosti-card\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>YouTube je druga najveća tražilica na svijetu</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-medium-font-size\"><em>Odmah iza Googlea — koji, usput, posjeduje YouTube.<br>Više ljudi traži upute i odgovore na YouTubeu<br>nego na Bingu, Yahoou i svim ostalima zajedno.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'Zanimljivosti', '', 'publish', 'closed', 'closed', '', 'zanimljivosti', '', '', '2026-06-02 19:26:42', '2026-06-02 19:26:42', '', 0, 'https://onlinekomunikacija.wordpress.com/?page_id=44', 0, 'page', '', 0),
