(96, 1, '2026-06-01 23:33:31', '2026-06-01 23:33:31', '<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Učestvuj u kratkoj anketi o društvenim mrežama i vidi kako su drugi odgovorili!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://petar-sys.github.io/anketa-sajt\">Idi na anketu</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->', 'Anketa', '', 'inherit', 'closed', 'closed', '', '19-revision-v1', '', '', '2026-06-01 23:33:31', '2026-06-01 23:33:31', '', 19, 'http://localhost/mywordpress/?p=96', 0, 'revision', '', 0),
(97, 1, '2026-06-01 23:35:51', '2026-06-01 23:35:51', '<!-- wp:paragraph -->\n<p>This is an example page. It\'s different from a blog post because it will stay in one place and will show up in your site navigation (in most themes). Most people start with an About page that introduces them to potential site visitors. It might say something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>Hi there! I\'m a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like pi&#241;a coladas. (And gettin\' caught in the rain.)</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>...or something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>As a new WordPress user, you should go to <a href=\"http://localhost/mywordpress/wp-admin/\">your dashboard</a> to delete this page and create new pages for your content. Have fun!</p>\n<!-- /wp:paragraph -->', 'Sample Page', '', 'inherit', 'closed', 'closed', '', '2-revision-v1', '', '', '2026-06-01 23:35:51', '2026-06-01 23:35:51', '', 2, 'http://localhost/mywordpress/?p=97', 0, 'revision', '', 0),
(98, 1, '2026-06-01 23:36:29', '2026-06-01 23:36:29', '<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we are</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Our website address is: http://localhost/mywordpress.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Comments</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>When visitors leave comments on the site we collect the data shown in the comments form, and also the visitor&#8217;s IP address and browser user agent string to help spam detection.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>An anonymized string created from your email address (also called a hash) may be provided to the Gravatar service to see if you are using it. The Gravatar service privacy policy is available here: https://automattic.com/privacy/. After approval of your comment, your profile picture is visible to the public in the context of your comment.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Media</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you upload images to the website, you should avoid uploading images with embedded location data (EXIF GPS) included. Visitors to the website can download and extract any location data from images on the website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Cookies</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment on our site you may opt-in to saving your name, email address and website in cookies. These are for your convenience so that you do not have to fill in your details again when you leave another comment. These cookies will last for one year.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you visit our login page, we will set a temporary cookie to determine if your browser accepts cookies. This cookie contains no personal data and is discarded when you close your browser.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>When you log in, we will also set up several cookies to save your login information and your screen display choices. Login cookies last for two days, and screen options cookies last for a year. If you select &quot;Remember Me&quot;, your login will persist for two weeks. If you log out of your account, the login cookies will be removed.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you edit or publish an article, an additional cookie will be saved in your browser. This cookie includes no personal data and simply indicates the post ID of the article you just edited. It expires after 1 day.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Embedded content from other websites</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we share your data with</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you request a password reset, your IP address will be included in the reset email.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How long we retain your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment, the comment and its metadata are retained indefinitely. This is so we can recognize and approve any follow-up comments automatically instead of holding them in a moderation queue.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>For users that register on our website (if any), we also store the personal information they provide in their user profile. All users can see, edit, or delete their personal information at any time (except they cannot change their username). Website administrators can also see and edit that information.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What rights you have over your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you have an account on this site, or have left comments, you can request to receive an exported file of the personal data we hold about you, including any data you have provided to us. You can also request that we erase any personal data we hold about you. This does not include any data we are obliged to keep for administrative, legal, or security purposes.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Where your data is sent</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Visitor comments may be checked through an automated spam detection service.</p>\n<!-- /wp:paragraph -->\n', 'Privacy Policy', '', 'inherit', 'closed', 'closed', '', '3-revision-v1', '', '', '2026-06-01 23:36:29', '2026-06-01 23:36:29', '', 3, 'http://localhost/mywordpress/?p=98', 0, 'revision', '', 0),
(99, 1, '2026-06-01 23:37:38', '2026-06-01 23:37:38', '{\"styles\":{\"css\":\":where(.wp-site-blocks *:focus) {\\n    outline-width: 2px;\\n    outline-style: solid;\\n}\\n\\n/* Hover efekat za dugmad */\\n.wp-block-button__link, \\nbutton, \\n.button,\\n.wp-block-button a {\\n    transition: all 0.2s ease;\\n}\\n\\n.wp-block-button__link:hover, \\nbutton:hover, \\n.button:hover {\\n    transform: scale(1.1);\\n}\\n\\n/* Hover efekat za kartice (card-box klasa) */\\n.card-box {\\n    transition: transform 0.3s ease, box-shadow 0.3s ease;\\n    border-radius: 16px;\\n}\\n\\n.card-box:hover {\\n    transform: translateY(-5px);\\n    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.15);\\n}\\n\\n/* Hover efekat za meni - podvla\\u010denje */\\n.main-navigation a, \\n.wp-block-navigation a {\\n    position: relative;\\n    text-decoration: none;\\n    transition: all 0.3s ease;\\n}\\n\\n.main-navigation a::after,\\n.wp-block-navigation a::after {\\n    content: \'\';\\n    position: absolute;\\n    bottom: -5px;\\n    left: 0;\\n    width: 0;\\n    height: 2px;\\n    background-color: #888888;\\n    transition: width 0.3s ease;\\n}\\n\\n.main-navigation a:hover::after,\\n.wp-block-navigation a:hover::after {\\n    width: 100%;\\n}\\n\\n.main-navigation a:hover,\\n.wp-block-navigation a:hover {\\n    transform: translateY(-2px);\\n}\\n\\n/* GRAYSCALE TABELA (globalno) */\\ntable {\\n    width: 100%;\\n    border-collapse: separate;\\n    border-spacing: 0;\\n    border-radius: 20px;\\n    overflow: hidden;\\n    box-shadow: 0 10px 25px rgba(0,0,0,0.08);\\n}\\n\\nth {\\n    background: linear-gradient(135deg, #2d2d2d 0%, #4a4a4a 100%);\\n    color: #ffffff;\\n    padding: 18px 16px;\\n    font-size: 1rem;\\n    font-weight: 600;\\n    text-transform: uppercase;\\n    letter-spacing: 1px;\\n}\\n\\ntd {\\n    padding: 14px 16px;\\n    background-color: #ffffff;\\n    border-bottom: 1px solid #e5e5e5;\\n    color: #333333;\\n}\\n\\ntr:last-child td {\\n    border-bottom: none;\\n}\\n\\ntbody tr:hover td {\\n    background-color: #f5f5f5;\\n}\\n\\ntd:first-child, th:first-child {\\n    font-weight: 600;\\n    border-right: 2px solid #e5e5e5;\\n}\\n\\ntbody tr:nth-child(even) td {\\n    background-color: #fafafa;\\n}\\n\\ntbody tr:nth-child(even):hover td {\\n    background-color: #f0f0f0;\\n}\\n\\n/* FADE IN EFEKAT */\\nbody {\\n    animation: fadeIn 0.5s ease-out;\\n}\\n\\n@keyframes fadeIn {\\n    0% { opacity: 0; }\\n    100% { opacity: 1; }\\n}\\n\\n/* PREMIUM DUGMAD - grayscale */\\n.wp-block-button__link, \\nbutton, \\n.button {\\n    transition: all 0.25s ease;\\n    position: relative;\\n    overflow: hidden;\\n    background-color: #4a4a4a !important;\\n    color: #ffffff !important;\\n    border-radius: 8px;\\n}\\n\\n.wp-block-button__link:hover, \\nbutton:hover, \\n.button:hover {\\n    transform: translateY(-2px);\\n    box-shadow: 0 8px 20px rgba(0,0,0,0.15);\\n    background-color: #333333 !important;\\n}\\n\\n.wp-block-button__link::before,\\nbutton::before {\\n    content: \'\';\\n    position: absolute;\\n    top: 0;\\n    left: -100%;\\n    width: 100%;\\n    height: 100%;\\n    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);\\n    transition: left 0.4s ease;\\n}\\n\\n.wp-block-button__link:hover::before,\\nbutton:hover::before {\\n    left: 100%;\\n}\\n\\n/* ========== STRANICA ZANIMLJIVOSTI (staklo, grayscale) ========== */\\n.zanimljivosti-grid {\\n    display: grid;\\n    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));\\n    gap: 30px;\\n    margin: 40px 0;\\n    background: linear-gradient(135deg, #ececec 0%, #dfdfdf 50%, #d2d2d2 100%);\\n    padding: 50px 40px;\\n    border-radius: 48px;\\n    position: relative;\\n    box-shadow: 0 15px 35px rgba(0,0,0,0.05);\\n}\\n\\n.zanimljivosti-card {\\n    background: rgba(255, 255, 255, 0.45);\\n    backdrop-filter: blur(12px);\\n    border-radius: 32px;\\n    padding: 28px;\\n    transition: all 0.3s ease;\\n    border: 1px solid rgba(255, 255, 255, 0.7);\\n    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.05);\\n}\\n\\n.zanimljivosti-card:hover {\\n    transform: translateY(-8px);\\n    background: rgba(255, 255, 255, 0.65);\\n    border-color: rgba(255, 255, 255, 0.9);\\n    box-shadow: 0 20px 35px rgba(0, 0, 0, 0.1);\\n}\\n\\n.zanimljivosti-card h3 {\\n    font-size: 1.5rem;\\n    font-weight: 700;\\n    margin-bottom: 16px;\\n    color: #1a1a1a;\\n    border-left: 4px solid #888888;\\n    padding-left: 16px;\\n}\\n\\n.zanimljivosti-card p {\\n    font-size: 1rem;\\n    line-height: 1.6;\\n    color: #2c2c2c;\\n    margin: 0;\\n}\\n\\n.zanimljivosti-section-title {\\n    font-size: 2rem;\\n    font-weight: 700;\\n    margin: 50px 0 25px 0;\\n    padding-bottom: 12px;\\n    border-bottom: 2px solid #aaaaaa;\\n    color: #1a1a1a;\\n    letter-spacing: -0.5px;\\n}\\n\\n.zanimljivosti-highlight {\\n    background: rgba(255, 255, 255, 0.4);\\n    backdrop-filter: blur(5px);\\n    padding: 24px 32px;\\n    border-radius: 28px;\\n    font-style: italic;\\n    font-size: 1.1rem;\\n    color: #1a1a1a;\\n    border-left: 4px solid #888888;\\n    margin: 30px 0;\\n}\\n\\n.zanimljivosti-stat {\\n    display: inline-block;\\n    font-size: 2.8rem;\\n    font-weight: 800;\\n    color: #4a4a4a;\\n    line-height: 1;\\n}\\n\\n.zanimljivosti-number {\\n    display: inline-block;\\n    font-size: 2.2rem;\\n    font-weight: 800;\\n    color: #bbbbbb;\\n    margin-bottom: 12px;\\n    letter-spacing: -2px;\\n}\\n\\n/* ========== STRANICA STATISTIKE (grayscale, staklo) ========== */\\n\\n/* Grid za 4 statistike (brojevi) */\\n.statistike-grid {\\n    display: grid;\\n    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\\n    gap: 25px;\\n    margin: 40px 0;\\n}\\n\\n/* Kartica za pojedina\\u010dnu statistiku */\\n.stat-card {\\n    background: rgba(255, 255, 255, 0.5);\\n    backdrop-filter: blur(8px);\\n    border-radius: 28px;\\n    padding: 28px 20px;\\n    text-align: center;\\n    transition: all 0.3s ease;\\n    border: 1px solid rgba(255, 255, 255, 0.7);\\n    box-shadow: 0 5px 15px rgba(0,0,0,0.03);\\n}\\n\\n.stat-card:hover {\\n    transform: translateY(-6px);\\n    background: rgba(255, 255, 255, 0.7);\\n    border-color: #ffffff;\\n    box-shadow: 0 15px 30px rgba(0,0,0,0.08);\\n}\\n\\n/* Broj (veliki) */\\n.stat-number {\\n    display: block;\\n    font-size: 3.2rem;\\n    font-weight: 800;\\n    color: #2a2a2a;\\n    line-height: 1.1;\\n    margin-bottom: 8px;\\n    letter-spacing: -1px;\\n}\\n\\n/* Opis ispod broja */\\n.stat-label {\\n    display: block;\\n    font-size: 0.95rem;\\n    font-weight: 500;\\n    color: #4a4a4a;\\n    text-transform: uppercase;\\n    letter-spacing: 0.5px;\\n}\\n\\n/* Tamna sekcija (Bosna i Hercegovina) - staklo varijanta */\\n.bih-section {\\n    background: rgba(200, 200, 200, 0.4);\\n    backdrop-filter: blur(8px);\\n    border-radius: 36px;\\n    padding: 40px 35px;\\n    margin: 50px 0;\\n    border: 1px solid rgba(255, 255, 255, 0.6);\\n    text-align: center;\\n    transition: all 0.3s ease;\\n}\\n\\n.bih-section:hover {\\n    background: rgba(200, 200, 200, 0.6);\\n    border-color: rgba(255, 255, 255, 0.8);\\n    box-shadow: 0 15px 30px rgba(0,0,0,0.05);\\n}\\n\\n.bih-section h2 {\\n    font-size: 2rem;\\n    font-weight: 700;\\n    color: #1a1a1a;\\n    margin-bottom: 20px;\\n}\\n\\n.bih-section p {\\n    font-size: 1.1rem;\\n    line-height: 1.5;\\n    color: #2c2c2c;\\n    max-width: 800px;\\n    margin-left: auto;\\n    margin-right: auto;\\n}\\n\\n/* Dugme u tamnoj sekciji (ako nije ve\\u0107 pokriveno globalnim) */\\n.bih-section .wp-block-button__link {\\n    margin-top: 20px;\\n    background-color: #4a4a4a !important;\\n}\"},\"isGlobalStylesUserThemeJSON\":true,\"version\":3}', 'Custom Styles', '', 'publish', 'closed', 'closed', '', 'wp-global-styles-twentytwentyfour', '', '', '2026-06-02 19:37:00', '2026-06-02 19:37:00', '', 0, 'http://localhost/mywordpress/index.php/2026/06/01/wp-global-styles-twentytwentyfour/', 0, 'wp_global_styles', '', 0),
(100, 1, '2026-06-01 23:38:12', '2026-06-01 23:38:12', '<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong><em>Zanimljivosti o internetu u BiH</em></strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"25px\",\"topRight\":\"25px\",\"bottomLeft\":\"25px\",\"bottomRight\":\"25px\"}}},\"gradient\":\"gradient-1\"} -->\n<div class=\"wp-block-columns alignwide has-gradient-1-gradient-background has-background\" style=\"border-top-left-radius:25px;border-top-right-radius:25px;border-bottom-left-radius:25px;border-bottom-right-radius:25px\"><!-- wp:column {\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>BiH i dijaspora online</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\",\"className\":\"is-style-default\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity is-style-default\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Procjenjuje se da van BiH živi više od 1,3 miliona Bosanaca. Većina njih ostaje u kontaktu s domovinom isključivo putem Facebooka i WhatsAppa.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>Facebook stariji od TikToka za cijelu generaciju</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Prosječni Facebook korisnik u BiH ima između 30 i 45 godina. Prosječni TikTok korisnik ima između 16 i 24. To su bukvalno dvije različite generacije na dva različita interneta.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>Vijesti? Na Facebooku.</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Više od 60% građana BiH primarno se informiše putem društvenih mreža, a ne tradicionalnih medija. Facebook je danas važniji od večernjih vijesti.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:image {\"id\":90,\"aspectRatio\":\"16/9\",\"scale\":\"cover\",\"focalPoint\":{\"x\":0.51,\"y\":0.51},\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"75px\",\"topRight\":\"75px\",\"bottomLeft\":\"75px\",\"bottomRight\":\"75px\"}},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}}}} -->\n<figure class=\"wp-block-image size-full has-custom-border\" style=\"margin-top:var(--wp--preset--spacing--30);margin-bottom:var(--wp--preset--spacing--30)\"><img src=\"http://localhost/mywordpress/wp-content/uploads/2026/05/sumup-aqc7znjxrom-unsplash-edited.jpg\" alt=\"\" class=\"wp-image-90\" style=\"border-top-left-radius:75px;border-top-right-radius:75px;border-bottom-left-radius:75px;border-bottom-right-radius:75px;aspect-ratio:16/9;object-fit:cover;object-position:51% 51%\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong><em>Globalne zanimljivosti o internetu</em></strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"25px\",\"topRight\":\"25px\",\"bottomLeft\":\"25px\",\"bottomRight\":\"25px\"}}},\"gradient\":\"gradient-2\"} -->\n<div class=\"wp-block-columns alignwide has-gradient-2-gradient-background has-background\" style=\"border-top-left-radius:25px;border-top-right-radius:25px;border-bottom-left-radius:25px;border-bottom-right-radius:25px\"><!-- wp:column {\"width\":\"25%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:25%\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>Internet je mlađi nego što misliš</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>World Wide Web dostupan je javnosti tek od 1991.<br>Cijela era društvenih mreža stara je manje od 35 godina.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>Svake minute na internetu…</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Svake minute šalje se oko 300 miliona emailova,<br>objavljuje 500 sati YouTube videa i pošalje<br>preko 41 milion WhatsApp poruka.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"25%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:25%\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>Više od polovine čovječanstva online</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"right\"}}} -->\n<p class=\"has-text-align-right\"><em>2024 godine više od 5,4 milijarde ljudi koristilo je internet - to je oko 67% ukupne svjetske populacije. Još prije 20 godina taj broj bio je ispod 15%.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:image {\"id\":92,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"75px\",\"topRight\":\"75px\",\"bottomLeft\":\"75px\",\"bottomRight\":\"75px\"}},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}}}} -->\n<figure class=\"wp-block-image size-large has-custom-border\" style=\"margin-top:var(--wp--preset--spacing--30);margin-bottom:var(--wp--preset--spacing--30)\"><img src=\"http://localhost/mywordpress/wp-content/uploads/2026/05/firmbee-com-dfmmzzi3rmg-unsplash-edited.jpg\" alt=\"\" class=\"wp-image-92\" style=\"border-top-left-radius:75px;border-top-right-radius:75px;border-bottom-left-radius:75px;border-bottom-right-radius:75px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong><em>Društvene mreže</em></strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"25px\",\"topRight\":\"25px\",\"bottomLeft\":\"25px\",\"bottomRight\":\"25px\"}}},\"gradient\":\"gradient-1\"} -->\n<div class=\"wp-block-columns alignwide has-gradient-1-gradient-background has-background\" style=\"border-top-left-radius:25px;border-top-right-radius:25px;border-bottom-left-radius:25px;border-bottom-right-radius:25px\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\"><em><strong>TikTok algoritam zna bolje od tebe</strong></em></h4>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-medium-font-size\"><em>TikTok može predvidjeti tvoje interese nakon samo<br>nekoliko minuta gledanja. Algoritam analizira čak<br>i to koliko dugo zastaneš na određenom videu.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\"><strong><em>Prosječan čovjek provede 6+ sati online dnevno</em></strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-medium-font-size\"><em>Od toga gotovo 2,5 sata otpada na društvene mreže.<br>U toku jedne godine to je više od 900 sati -<br>ili cijela 37 dana neprekidnog skrolanja.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\"><strong><em>YouTube je druga najveća tražilica na svijetu</em></strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-medium-font-size\"><em>Odmah iza Googlea — koji, usput, posjeduje YouTube.<br>Više ljudi traži upute i odgovore na YouTubeu<br>nego na Bingu, Yahoou i svim ostalima zajedno.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->', 'Zanimljivosti', '', 'inherit', 'closed', 'closed', '', '44-revision-v1', '', '', '2026-06-01 23:38:12', '2026-06-01 23:38:12', '', 44, 'http://localhost/mywordpress/?p=100', 0, 'revision', '', 0);
