(107, 1, '2026-06-02 18:05:17', '2026-06-02 18:05:17', '{\"styles\":{\"css\":\"/* Glavne boje za cijeli sajt */\\n:root {\\n    --primary-color: #00A8B5;\\n    --header-bg: #0A2540;\\n}\\n\\n/* Navigacija - tamno plava pozadina */\\n.site-header, .main-navigation, .wp-block-site-header {\\n    background-color: var(--header-bg) !important;\\n}\\n\\n.site-header a, .main-navigation a, .wp-block-navigation a {\\n    color: #ffffff !important;\\n}\\n\\n/* Dugmad - tirkizna boja */\\n.wp-block-button__link, button, .button {\\n    background-color: var(--primary-color) !important;\\n    color: #ffffff !important;\\n    border-radius: 8px;\\n}\\n\\n/* Linkovi */\\na {\\n    color: var(--primary-color) !important;\\n    text-decoration: none;\\n}\\n\\na:hover {\\n    text-decoration: underline;\\n}\\n\\n/* Citat blok - gradijent */\\n.wp-block-quote {\\n    background: linear-gradient(135deg, #3A7BD5 0%, #1E3A8A 100%);\\n    color: #ffffff;\\n    border-radius: 16px;\\n    padding: 2rem;\\n}\\n\\n/* Kartice - hover efekat */\\n.wp-block-column, .wp-block-group {\\n    transition: transform 0.2s ease, box-shadow 0.2s ease;\\n}\\n\\n.wp-block-column:hover, .wp-block-group:hover {\\n    transform: translateY(-5px);\\n    box-shadow: 0 10px 20px rgba(0,168,181,0.2);\\n}\"},\"isGlobalStylesUserThemeJSON\":true,\"version\":3}', 'Custom Styles', '', 'inherit', 'closed', 'closed', '', '99-revision-v1', '', '', '2026-06-02 18:05:17', '2026-06-02 18:05:17', '', 99, 'http://localhost/mywordpress/?p=107', 0, 'revision', '', 0),
