(109, 1, '2026-06-02 18:09:57', '2026-06-02 18:09:57', '{\"styles\":{\"css\":\"/* Glavne boje */\\n:root {\\n    --primary-color: #00A8B5;\\n    --header-bg: #0A2540;\\n}\\n\\n/* Navigacija - tamno plava */\\n.site-header, .main-navigation, .wp-block-site-header {\\n    background-color: var(--header-bg) !important;\\n}\\n\\n.site-header a, .main-navigation a, .wp-block-navigation a {\\n    color: #ffffff !important;\\n}\\n\\n/* Dugmad - tirkizna */\\n.wp-block-button__link, button, .button {\\n    background-color: var(--primary-color) !important;\\n    color: #ffffff !important;\\n    border-radius: 8px;\\n}\\n\\n/* Linkovi */\\na {\\n    color: var(--primary-color) !important;\\n}\\n\\n/* Citat blok */\\n.wp-block-quote {\\n    background: linear-gradient(135deg, #3A7BD5 0%, #1E3A8A 100%);\\n    color: #ffffff;\\n    border-radius: 16px;\\n    padding: 2rem;\\n}\\n\\n/* HOVER SAMO NA KARTICAMA (Columns) - bez pomjeranja, samo blagi sjaj */\\n.wp-block-column {\\n    transition: box-shadow 0.3s ease;\\n    border-radius: 12px;\\n}\\n\\n.wp-block-column:hover {\\n    box-shadow: 0 8px 20px rgba(0,168,181,0.2);\\n}\\n/* Hover efekat samo za kartice sa custom klasom */\\n.hover-card {\\n    transition: transform 0.3s ease, box-shadow 0.3s ease;\\n    border-radius: 16px;\\n}\\n\\n.hover-card:hover {\\n    transform: scale(1.03);\\n    box-shadow: 0 15px 30px rgba(0,168,181,0.25);\\n}\"},\"isGlobalStylesUserThemeJSON\":true,\"version\":3}', 'Custom Styles', '', 'inherit', 'closed', 'closed', '', '99-revision-v1', '', '', '2026-06-02 18:09:57', '2026-06-02 18:09:57', '', 99, 'http://localhost/mywordpress/?p=109', 0, 'revision', '', 0);
