(144, 1, '2026-06-02 18:52:45', '2026-06-02 18:52:45', '<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\"><!-- wp:group {\"metadata\":{\"name\":\"About\"},\"align\":\"wide\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}},\"border\":{\"radius\":\"16px\"},\"background\":{\"backgroundSize\":\"contain\",\"backgroundRepeat\":\"no-repeat\",\"backgroundPosition\":\"45% 0%\"}},\"backgroundColor\":\"base\",\"fontSize\":\"small\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide has-base-background-color has-background has-small-font-size\" style=\"border-radius:16px;padding-top:var(--wp--preset--spacing--40);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--40);padding-left:var(--wp--preset--spacing--40)\"><!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":\"1.5rem\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"stretch\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:group {\"align\":\"wide\",\"style\":{\"typography\":{\"textTransform\":\"none\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|primary\"}}}},\"textColor\":\"primary\",\"fontSize\":\"small\",\"fontFamily\":\"inter-tight\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"stretch\"}} -->\n<div class=\"wp-block-group alignwide has-primary-color has-text-color has-link-color has-inter-tight-font-family has-small-font-size\" style=\"text-transform:none\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Za samo pet godina, više od milijardu novih korisnika priključilo se globalnoj digitalnoj mreži. Danas internet koristi 5,56 milijardi ljudi – više nego što gleda televiziju.</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"var:preset|spacing|10\"} -->\n<div style=\"height:var(--wp--preset--spacing--10)\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Stats\"},\"align\":\"wide\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"padding-right:0;padding-left:0\"><!-- wp:columns {\"metadata\":{\"name\":\"Stats\"},\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"className\":\"card-box\"} -->\n<div class=\"wp-block-column card-box\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"x-large\"} -->\n<h3 class=\"wp-block-heading has-text-align-center has-x-large-font-size\">5,5+ mlrd</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">korisnika interneta globalno</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"card-box\"} -->\n<div class=\"wp-block-column card-box\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"x-large\"} -->\n<h3 class=\"wp-block-heading has-text-align-center has-x-large-font-size\">4,6+ mlrd</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">korisnika društvenih mreža</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"card-box\"} -->\n<div class=\"wp-block-column card-box\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"x-large\"} -->\n<h3 class=\"wp-block-heading has-text-align-center has-x-large-font-size\">6h 30+ min</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">prosječno dnevno online</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"card-box\"} -->\n<div class=\"wp-block-column card-box\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"x-large\"} -->\n<h3 class=\"wp-block-heading has-text-align-center is-style-default has-x-large-font-size\">+1 mlrd</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">novih korisnika od 2020.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"categories\":[\"banner\"],\"patternName\":\"twentytwentyfour/cta-content-image-on-right\",\"name\":\"Event details\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}},\"heading\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"backgroundColor\":\"accent-5\",\"textColor\":\"contrast\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-contrast-color has-accent-5-background-color has-text-color has-background has-link-color\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\"><!-- wp:columns {\"verticalAlignment\":\"center\",\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\"}}}} -->\n<div class=\"wp-block-columns alignwide are-vertically-aligned-center\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:50%\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\"><strong><em>Kako stoji Bosna i Hercegovina?</em></strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"fontSize\":\"small\"} -->\n<p class=\"has-small-font-size\"><em>BiH bilježi 86,7% penetraciju interneta sa 2,73 miliona korisnika. U posljednjih godinu dana broj korisnika porastao je za 3,2%, što pokazuje da digitalizacija ubrzano napreduje i u našoj zemlji.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"is-style-fill\"} -->\n<div class=\"wp-block-button is-style-fill\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/mywordpress/bih-kontekst/\">Istraži BiH statistiku</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:50%\"><!-- wp:image {\"id\":78,\"aspectRatio\":\"4/3\",\"scale\":\"cover\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"className\":\"is-style-default\",\"style\":{\"color\":{\"duotone\":\"unset\"}}} -->\n<figure class=\"wp-block-image size-full is-style-default\"><img src=\"http://localhost/mywordpress/wp-content/uploads/2026/05/yogas-design-j6qn9se4akm-unsplash.jpg\" alt=\"\" class=\"wp-image-78\" style=\"aspect-ratio:4/3;object-fit:cover\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Call to action\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\"><!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>Najpopularnije platforme u 2025. godini</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:table {\"align\":\"wide\",\"className\":\"is-style-stripes\",\"style\":{\"border\":{\"width\":\"4px\"},\"typography\":{\"fontSize\":\"1.3rem\"}},\"gradient\":\"gradient-5\"} -->\n<figure class=\"wp-block-table alignwide is-style-stripes\" style=\"font-size:1.3rem\"><table class=\"has-gradient-5-gradient-background has-background has-fixed-layout\" style=\"border-width:4px\"><thead><tr><th class=\"has-text-align-center\" data-align=\"center\">Platforma</th><th class=\"has-text-align-center\" data-align=\"center\">Broj korisnika</th><th class=\"has-text-align-center\" data-align=\"center\">Glavna grupa</th></tr></thead><tbody><tr><td class=\"has-text-align-center\" data-align=\"center\">Facebook</td><td class=\"has-text-align-center\" data-align=\"center\">3,07 milijarde</td><td class=\"has-text-align-center\" data-align=\"center\">25–45 godina</td></tr><tr><td class=\"has-text-align-center\" data-align=\"center\">YouTube</td><td class=\"has-text-align-center\" data-align=\"center\">2,50 milijarde</td><td class=\"has-text-align-center\" data-align=\"center\">Svi uzrasti</td></tr><tr><td class=\"has-text-align-center\" data-align=\"center\">Instagram</td><td class=\"has-text-align-center\" data-align=\"center\">2,00 milijarde</td><td class=\"has-text-align-center\" data-align=\"center\">18–34 godina</td></tr><tr><td class=\"has-text-align-center\" data-align=\"center\">TikTok</td><td class=\"has-text-align-center\" data-align=\"center\">1,50 milijarde</td><td class=\"has-text-align-center\" data-align=\"center\">13–24 godina</td></tr><tr><td class=\"has-text-align-center\" data-align=\"center\">WhatsApp</td><td class=\"has-text-align-center\" data-align=\"center\">2,78 milijarde</td><td class=\"has-text-align-center\" data-align=\"center\">25–45 godina</td></tr></tbody></table></figure>\n<!-- /wp:table --></div>\n<!-- /wp:group -->', 'Statistike', '', 'inherit', 'closed', 'closed', '', '15-revision-v1', '', '', '2026-06-02 18:52:45', '2026-06-02 18:52:45', '', 15, 'http://localhost/mywordpress/?p=144', 0, 'revision', '', 0),
