(150, 1, '2026-06-02 19:00:56', '2026-06-02 19:00:56', '{\"styles\":{\"css\":\":where(.wp-site-blocks *:focus){outline-width:2px;outline-style:solid}\\n/* Hover efekat samo za kartice */\\n/* Hover efekat za dugmad */\\n.wp-block-button__link, \\nbutton, \\n.button,\\n.wp-block-button a {\\n    transition: all 0.2s ease;\\n}\\n\\n.wp-block-button__link:hover, \\nbutton:hover, \\n.button:hover {\\n    transform: scale(1.1);\\n  \\n}\\n\\n/* Hover efekat za kartice */\\n.card-box {\\n    transition: transform 0.3s ease, box-shadow 0.3s ease;\\n    border-radius: 16px;\\n}\\n\\n.card-box:hover {\\n    transform: translateY(-5px);\\n    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.15);\\n}\\n\\n/* Hover efekat za meni - podvla\\u010denje */\\n.main-navigation a, \\n.wp-block-navigation a {\\n    position: relative;\\n    text-decoration: none;\\n    transition: all 0.3s ease;\\n}\\n\\n/* Efekat podvla\\u010denja - linija dolazi ispod teksta */\\n.main-navigation a::after,\\n.wp-block-navigation a::after {\\n    content: \'\';\\n    position: absolute;\\n    bottom: -5px;\\n    left: 0;\\n    width: 0;\\n    height: 2px;\\n    background-color: #888888;\\n    transition: width 0.3s ease;\\n}\\n\\n/* Na hover - linija se razvla\\u010di */\\n.main-navigation a:hover::after,\\n.wp-block-navigation a:hover::after {\\n    width: 100%;\\n}\\n\\n/* Blago podizanje teksta na hover */\\n.main-navigation a:hover,\\n.wp-block-navigation a:hover {\\n    transform: translateY(-2px);\\n}\\n\\n/* 1. BRUTALNA TABELA */\\ntable {\\n    width: 100%;\\n    border-collapse: separate;\\n    border-spacing: 0;\\n    border-radius: 20px;\\n    overflow: hidden;\\n    box-shadow: 0 10px 30px rgba(0,0,0,0.08);\\n}\\n\\nth {\\n    background: linear-gradient(135deg, #1e3a8a 0%, #3b82f6 100%);\\n    color: white;\\n    padding: 18px 16px;\\n    font-size: 1rem;\\n    font-weight: 600;\\n    text-transform: uppercase;\\n    letter-spacing: 1px;\\n}\\n\\ntd {\\n    padding: 14px 16px;\\n    background-color: white;\\n    border-bottom: 1px solid #eef2f6;\\n    color: #1a2a3a;\\n}\\n\\ntr:last-child td {\\n    border-bottom: none;\\n}\\n\\ntbody tr:hover td {\\n    background: linear-gradient(90deg, #f8fafc 0%, #f1f5f9 100%);\\n    cursor: pointer;\\n}\\n\\ntd:first-child, th:first-child {\\n    font-weight: 600;\\n    border-right: 2px solid #eef2f6;\\n}\\n\\ntbody tr:nth-child(even) td {\\n    background-color: #f9fafb;\\n}\\n\\n/* 2. FADE IN EFEKAT */\\nbody {\\n    animation: fadeSlideUp 0.6s cubic-bezier(0.2, 0.9, 0.4, 1.1);\\n}\\n\\n@keyframes fadeSlideUp {\\n    from {\\n        opacity: 0;\\n        transform: translateY(20px);\\n    }\\n    to {\\n        opacity: 1;\\n        transform: translateY(0);\\n    }\\n}\\n\\n/* 3. PREMIUM DUGMAD */\\n.wp-block-button__link, button, .button {\\n    transition: all 0.3s cubic-bezier(0.2, 0.9, 0.4, 1.1);\\n    position: relative;\\n    overflow: hidden;\\n}\\n\\n.wp-block-button__link:hover, button:hover, .button:hover {\\n    transform: translateY(-3px);\\n    box-shadow: 0 10px 25px rgba(0,0,0,0.15);\\n}\\n\\n.wp-block-button__link::before, button::before {\\n    content: \'\';\\n    position: absolute;\\n    top: 0;\\n    left: -100%;\\n    width: 100%;\\n    height: 100%;\\n    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.3), transparent);\\n    transition: left 0.5s ease;\\n}\\n\\n.wp-block-button__link:hover::before, button:hover::before {\\n    left: 100%;\\n}\"},\"isGlobalStylesUserThemeJSON\":true,\"version\":3}', 'Custom Styles', '', 'inherit', 'closed', 'closed', '', '99-revision-v1', '', '', '2026-06-02 19:00:56', '2026-06-02 19:00:56', '', 99, 'http://localhost/mywordpress/?p=150', 0, 'revision', '', 0),
(151, 1, '2026-06-02 19:02:26', '2026-06-02 19:02:26', '{\"styles\":{\"css\":\":where(.wp-site-blocks *:focus){outline-width:2px;outline-style:solid}\\n/* Hover efekat samo za kartice */\\n/* Hover efekat za dugmad */\\n.wp-block-button__link, \\nbutton, \\n.button,\\n.wp-block-button a {\\n    transition: all 0.2s ease;\\n}\\n\\n.wp-block-button__link:hover, \\nbutton:hover, \\n.button:hover {\\n    transform: scale(1.1);\\n  \\n}\\n\\n/* Hover efekat za kartice */\\n.card-box {\\n    transition: transform 0.3s ease, box-shadow 0.3s ease;\\n    border-radius: 16px;\\n}\\n\\n.card-box:hover {\\n    transform: translateY(-5px);\\n    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.15);\\n}\\n\\n/* Hover efekat za meni - podvla\\u010denje */\\n.main-navigation a, \\n.wp-block-navigation a {\\n    position: relative;\\n    text-decoration: none;\\n    transition: all 0.3s ease;\\n}\\n\\n/* Efekat podvla\\u010denja - linija dolazi ispod teksta */\\n.main-navigation a::after,\\n.wp-block-navigation a::after {\\n    content: \'\';\\n    position: absolute;\\n    bottom: -5px;\\n    left: 0;\\n    width: 0;\\n    height: 2px;\\n    background-color: #888888;\\n    transition: width 0.3s ease;\\n}\\n\\n/* Na hover - linija se razvla\\u010di */\\n.main-navigation a:hover::after,\\n.wp-block-navigation a:hover::after {\\n    width: 100%;\\n}\\n\\n/* Blago podizanje teksta na hover */\\n.main-navigation a:hover,\\n.wp-block-navigation a:hover {\\n    transform: translateY(-2px);\\n}\\n\\n/* 1. GRAYSCALE TABELA - \\u010dist, profesionalan izgled */\\ntable {\\n    width: 100%;\\n    border-collapse: separate;\\n    border-spacing: 0;\\n    border-radius: 20px;\\n    overflow: hidden;\\n    box-shadow: 0 10px 25px rgba(0,0,0,0.08);\\n}\\n\\n/* Zaglavlje tabele - tamno sivo */\\nth {\\n    background: linear-gradient(135deg, #2d2d2d 0%, #4a4a4a 100%);\\n    color: #ffffff;\\n    padding: 18px 16px;\\n    font-size: 1rem;\\n    font-weight: 600;\\n    text-transform: uppercase;\\n    letter-spacing: 1px;\\n}\\n\\n/* \\u0106elije tabele */\\ntd {\\n    padding: 14px 16px;\\n    background-color: #ffffff;\\n    border-bottom: 1px solid #e5e5e5;\\n    color: #333333;\\n}\\n\\n/* Zadnji red - bez bordera */\\ntr:last-child td {\\n    border-bottom: none;\\n}\\n\\n/* Hover efekat na red - svijetlo siva */\\ntbody tr:hover td {\\n    background-color: #f5f5f5;\\n}\\n\\n/* Prva kolona - podebljana */\\ntd:first-child, th:first-child {\\n    font-weight: 600;\\n    border-right: 2px solid #e5e5e5;\\n}\\n\\n/* Naizmjeni\\u010dne boje redova */\\ntbody tr:nth-child(even) td {\\n    background-color: #fafafa;\\n}\\n\\ntbody tr:nth-child(even):hover td {\\n    background-color: #f0f0f0;\\n}\\n\\n/* 2. FADE IN EFEKAT - popravljen, bez bagova */\\nbody {\\n    animation: fadeIn 0.5s ease-out;\\n}\\n\\n@keyframes fadeIn {\\n    0% {\\n        opacity: 0;\\n    }\\n    100% {\\n        opacity: 1;\\n    }\\n}\\n\\n/* 3. PREMIUM DUGMAD - grayscale verzija */\\n.wp-block-button__link, \\nbutton, \\n.button {\\n    transition: all 0.25s ease;\\n    position: relative;\\n    overflow: hidden;\\n    background-color: #4a4a4a !important;\\n    color: #ffffff !important;\\n    border-radius: 8px;\\n}\\n\\n.wp-block-button__link:hover, \\nbutton:hover, \\n.button:hover {\\n    transform: translateY(-2px);\\n    box-shadow: 0 8px 20px rgba(0,0,0,0.15);\\n    background-color: #333333 !important;\\n}\\n\\n/* Sjaj efekat na dugmad */\\n.wp-block-button__link::before,\\nbutton::before {\\n    content: \'\';\\n    position: absolute;\\n    top: 0;\\n    left: -100%;\\n    width: 100%;\\n    height: 100%;\\n    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);\\n    transition: left 0.4s ease;\\n}\\n\\n.wp-block-button__link:hover::before,\\nbutton:hover::before {\\n    left: 100%;\\n}\"},\"isGlobalStylesUserThemeJSON\":true,\"version\":3}', 'Custom Styles', '', 'inherit', 'closed', 'closed', '', '99-revision-v1', '', '', '2026-06-02 19:02:26', '2026-06-02 19:02:26', '', 99, 'http://localhost/mywordpress/?p=151', 0, 'revision', '', 0),
(152, 1, '2026-06-02 19:05:24', '2026-06-02 19:05:24', '{\"styles\":{\"css\":\":where(.wp-site-blocks *:focus){outline-width:2px;outline-style:solid}\\n/* Hover efekat samo za kartice */\\n/* Hover efekat za dugmad */\\n.wp-block-button__link, \\nbutton, \\n.button,\\n.wp-block-button a {\\n    transition: all 0.2s ease;\\n}\\n\\n.wp-block-button__link:hover, \\nbutton:hover, \\n.button:hover {\\n    transform: scale(1.1);\\n  \\n}\\n\\n/* Hover efekat za kartice */\\n.card-box {\\n    transition: transform 0.3s ease, box-shadow 0.3s ease;\\n    border-radius: 16px;\\n}\\n\\n.card-box:hover {\\n    transform: translateY(-5px);\\n    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.15);\\n}\\n\\n/* Hover efekat za meni - podvla\\u010denje */\\n.main-navigation a, \\n.wp-block-navigation a {\\n    position: relative;\\n    text-decoration: none;\\n    transition: all 0.3s ease;\\n}\\n\\n/* Efekat podvla\\u010denja - linija dolazi ispod teksta */\\n.main-navigation a::after,\\n.wp-block-navigation a::after {\\n    content: \'\';\\n    position: absolute;\\n    bottom: -5px;\\n    left: 0;\\n    width: 0;\\n    height: 2px;\\n    background-color: #888888;\\n    transition: width 0.3s ease;\\n}\\n\\n/* Na hover - linija se razvla\\u010di */\\n.main-navigation a:hover::after,\\n.wp-block-navigation a:hover::after {\\n    width: 100%;\\n}\\n\\n/* Blago podizanje teksta na hover */\\n.main-navigation a:hover,\\n.wp-block-navigation a:hover {\\n    transform: translateY(-2px);\\n}\\n\\n/* 1. GRAYSCALE TABELA - \\u010dist, profesionalan izgled */\\ntable {\\n    width: 100%;\\n    border-collapse: separate;\\n    border-spacing: 0;\\n    border-radius: 20px;\\n    overflow: hidden;\\n    box-shadow: 0 10px 25px rgba(0,0,0,0.08);\\n}\\n\\n/* Zaglavlje tabele - tamno sivo */\\nth {\\n    background: linear-gradient(135deg, #2d2d2d 0%, #4a4a4a 100%);\\n    color: #ffffff;\\n    padding: 18px 16px;\\n    font-size: 1rem;\\n    font-weight: 600;\\n    text-transform: uppercase;\\n    letter-spacing: 1px;\\n}\\n\\n/* \\u0106elije tabele */\\ntd {\\n    padding: 14px 16px;\\n    background-color: #ffffff;\\n    border-bottom: 1px solid #e5e5e5;\\n    color: #333333;\\n}\\n\\n/* Zadnji red - bez bordera */\\ntr:last-child td {\\n    border-bottom: none;\\n}\\n\\n/* Hover efekat na red - svijetlo siva */\\ntbody tr:hover td {\\n    background-color: #f5f5f5;\\n}\\n\\n/* Prva kolona - podebljana */\\ntd:first-child, th:first-child {\\n    font-weight: 600;\\n    border-right: 2px solid #e5e5e5;\\n}\\n\\n/* Naizmjeni\\u010dne boje redova */\\ntbody tr:nth-child(even) td {\\n    background-color: #fafafa;\\n}\\n\\ntbody tr:nth-child(even):hover td {\\n    background-color: #f0f0f0;\\n}\\n\\n/* 2. FADE IN EFEKAT - popravljen, bez bagova */\\nbody {\\n    animation: fadeIn 0.5s ease-out;\\n}\\n\\n@keyframes fadeIn {\\n    0% {\\n        opacity: 0;\\n    }\\n    100% {\\n        opacity: 1;\\n    }\\n}\\n\\n/* 3. PREMIUM DUGMAD - grayscale verzija */\\n.wp-block-button__link, \\nbutton, \\n.button {\\n    transition: all 0.25s ease;\\n    position: relative;\\n    overflow: hidden;\\n    background-color: #4a4a4a !important;\\n    color: #ffffff !important;\\n    border-radius: 8px;\\n}\\n\\n.wp-block-button__link:hover, \\nbutton:hover, \\n.button:hover {\\n    transform: translateY(-2px);\\n    box-shadow: 0 8px 20px rgba(0,0,0,0.15);\\n    background-color: #333333 !important;\\n}\\n\\n/* Sjaj efekat na dugmad */\\n.wp-block-button__link::before,\\nbutton::before {\\n    content: \'\';\\n    position: absolute;\\n    top: 0;\\n    left: -100%;\\n    width: 100%;\\n    height: 100%;\\n    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);\\n    transition: left 0.4s ease;\\n}\\n\\n.wp-block-button__link:hover::before,\\nbutton:hover::before {\\n    left: 100%;\\n}\\n\\n/* ========== SAMO ZA STRANICU ZANIMLJIVOSTI ========== */\\n\\n/* Kontejner za sve kartice */\\n.zanimljivosti-grid {\\n    display: grid;\\n    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));\\n    gap: 30px;\\n    margin: 40px 0;\\n}\\n\\n/* Kartica - grayscale stil */\\n.zanimljivosti-card {\\n    background: #ffffff;\\n    border-radius: 24px;\\n    padding: 28px;\\n    box-shadow: 0 5px 15px rgba(0,0,0,0.05);\\n    transition: all 0.3s ease;\\n    border: 1px solid #e8e8e8;\\n}\\n\\n.zanimljivosti-card:hover {\\n    transform: translateY(-8px);\\n    box-shadow: 0 20px 35px rgba(0,0,0,0.1);\\n}\\n\\n/* Naslov kartice */\\n.zanimljivosti-card h3 {\\n    font-size: 1.5rem;\\n    font-weight: 700;\\n    margin-bottom: 16px;\\n    color: #1a1a1a;\\n    border-left: 4px solid #888888;\\n    padding-left: 16px;\\n}\\n\\n/* Tekst kartice */\\n.zanimljivosti-card p {\\n    font-size: 1rem;\\n    line-height: 1.6;\\n    color: #3a3a3a;\\n    margin: 0;\\n}\\n\\n/* Broj ili ikonica na kartici */\\n.zanimljivosti-number {\\n    display: inline-block;\\n    font-size: 2.5rem;\\n    font-weight: 800;\\n    color: #cccccc;\\n    margin-bottom: 12px;\\n    letter-spacing: -2px;\\n}\\n\\n/* Sekcija naslov (izme\\u0111u grupa kartica) */\\n.zanimljivosti-section-title {\\n    font-size: 2rem;\\n    font-weight: 700;\\n    margin: 50px 0 25px 0;\\n    padding-bottom: 12px;\\n    border-bottom: 2px solid #e0e0e0;\\n    color: #222222;\\n}\\n\\n/* Citat / istaknuti tekst */\\n.zanimljivosti-highlight {\\n    background: #f5f5f5;\\n    padding: 24px 32px;\\n    border-radius: 20px;\\n    font-style: italic;\\n    font-size: 1.1rem;\\n    color: #333;\\n    border-left: 4px solid #888888;\\n    margin: 30px 0;\\n}\\n\\n/* Statistika - veliki brojevi */\\n.zanimljivosti-stat {\\n    display: inline-block;\\n    font-size: 3rem;\\n    font-weight: 800;\\n    color: #4a4a4a;\\n    line-height: 1;\\n}\\n\\n/* Dugme na kartici */\\n.zanimljivosti-btn {\\n    display: inline-block;\\n    margin-top: 20px;\\n    padding: 10px 20px;\\n    background: #4a4a4a;\\n    color: white;\\n    border-radius: 30px;\\n    font-size: 0.85rem;\\n    text-decoration: none;\\n    transition: all 0.25s ease;\\n}\\n\\n.zanimljivosti-btn:hover {\\n    background: #2a2a2a;\\n    transform: translateX(5px);\\n}\"},\"isGlobalStylesUserThemeJSON\":true,\"version\":3}', 'Custom Styles', '', 'inherit', 'closed', 'closed', '', '99-revision-v1', '', '', '2026-06-02 19:05:24', '2026-06-02 19:05:24', '', 99, 'http://localhost/mywordpress/?p=152', 0, 'revision', '', 0),
(153, 1, '2026-06-02 19:08:40', '2026-06-02 19:08:40', '<!-- wp:heading {\"className\":\"zanimljivosti-section-title\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center zanimljivosti-section-title\"><strong><em>Zanimljivosti o internetu u BiH</em></strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"align\":\"wide\",\"className\":\"zanimljivosti-grid\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"25px\",\"topRight\":\"25px\",\"bottomLeft\":\"25px\",\"bottomRight\":\"25px\"}}},\"gradient\":\"gradient-1\"} -->\n<div class=\"wp-block-columns alignwide zanimljivosti-grid has-gradient-1-gradient-background has-background\" style=\"border-top-left-radius:25px;border-top-right-radius:25px;border-bottom-left-radius:25px;border-bottom-right-radius:25px\"><!-- wp:column {\"className\":\"zanimljivosti-card\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-column zanimljivosti-card\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>BiH i dijaspora online</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\",\"className\":\"is-style-default\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity is-style-default\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Procjenjuje se da van BiH živi više od 1,3 miliona Bosanaca. Većina njih ostaje u kontaktu s domovinom isključivo putem Facebooka i WhatsAppa.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"zanimljivosti-card\"} -->\n<div class=\"wp-block-column zanimljivosti-card\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>Facebook stariji od TikToka za cijelu generaciju</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Prosječni Facebook korisnik u BiH ima između 30 i 45 godina. Prosječni TikTok korisnik ima između 16 i 24. To su bukvalno dvije različite generacije na dva različita interneta.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"zanimljivosti-card\"} -->\n<div class=\"wp-block-column zanimljivosti-card\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>Vijesti? Na Facebooku.</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Više od 60% građana BiH primarno se informiše putem društvenih mreža, a ne tradicionalnih medija. Facebook je danas važniji od večernjih vijesti.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:image {\"id\":90,\"aspectRatio\":\"16/9\",\"scale\":\"cover\",\"focalPoint\":{\"x\":0.51,\"y\":0.51},\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"75px\",\"topRight\":\"75px\",\"bottomLeft\":\"75px\",\"bottomRight\":\"75px\"}},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}}}} -->\n<figure class=\"wp-block-image size-full has-custom-border\" style=\"margin-top:var(--wp--preset--spacing--30);margin-bottom:var(--wp--preset--spacing--30)\"><img src=\"http://localhost/mywordpress/wp-content/uploads/2026/05/sumup-aqc7znjxrom-unsplash-edited.jpg\" alt=\"\" class=\"wp-image-90\" style=\"border-top-left-radius:75px;border-top-right-radius:75px;border-bottom-left-radius:75px;border-bottom-right-radius:75px;aspect-ratio:16/9;object-fit:cover;object-position:51% 51%\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"className\":\"zanimljivosti-section-title\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center zanimljivosti-section-title\"><strong><em>Globalne zanimljivosti o internetu</em></strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"align\":\"wide\",\"className\":\"zanimljivosti-grid\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"25px\",\"topRight\":\"25px\",\"bottomLeft\":\"25px\",\"bottomRight\":\"25px\"}}},\"gradient\":\"gradient-2\"} -->\n<div class=\"wp-block-columns alignwide zanimljivosti-grid has-gradient-2-gradient-background has-background\" style=\"border-top-left-radius:25px;border-top-right-radius:25px;border-bottom-left-radius:25px;border-bottom-right-radius:25px\"><!-- wp:column {\"width\":\"25%\",\"className\":\"zanimljivosti-card\"} -->\n<div class=\"wp-block-column zanimljivosti-card\" style=\"flex-basis:25%\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>Internet je mlađi nego što misliš</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>World Wide Web dostupan je javnosti tek od 1991.<br>Cijela era društvenih mreža stara je manje od 35 godina.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\",\"className\":\"zanimljivosti-card\"} -->\n<div class=\"wp-block-column zanimljivosti-card\" style=\"flex-basis:50%\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>Svake minute na internetu…</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Svake minute šalje se oko 300 miliona emailova,<br>objavljuje 500 sati YouTube videa i pošalje<br>preko 41 milion WhatsApp poruka.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"25%\",\"className\":\"zanimljivosti-card\"} -->\n<div class=\"wp-block-column zanimljivosti-card\" style=\"flex-basis:25%\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong><em>Više od polovine čovječanstva online</em></strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"right\"}}} -->\n<p class=\"has-text-align-right\"><em>2024 godine više od 5,4 milijarde ljudi koristilo je internet - to je oko 67% ukupne svjetske populacije. Još prije 20 godina taj broj bio je ispod 15%.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:image {\"id\":92,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"75px\",\"topRight\":\"75px\",\"bottomLeft\":\"75px\",\"bottomRight\":\"75px\"}},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}}}} -->\n<figure class=\"wp-block-image size-large has-custom-border\" style=\"margin-top:var(--wp--preset--spacing--30);margin-bottom:var(--wp--preset--spacing--30)\"><img src=\"http://localhost/mywordpress/wp-content/uploads/2026/05/firmbee-com-dfmmzzi3rmg-unsplash-edited.jpg\" alt=\"\" class=\"wp-image-92\" style=\"border-top-left-radius:75px;border-top-right-radius:75px;border-bottom-left-radius:75px;border-bottom-right-radius:75px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"className\":\"zanimljivosti-section-title\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center zanimljivosti-section-title\"><strong><em>Društvene mreže</em></strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"align\":\"wide\",\"className\":\"zanimljivosti-grid\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"25px\",\"topRight\":\"25px\",\"bottomLeft\":\"25px\",\"bottomRight\":\"25px\"}}},\"gradient\":\"gradient-1\"} -->\n<div class=\"wp-block-columns alignwide zanimljivosti-grid has-gradient-1-gradient-background has-background\" style=\"border-top-left-radius:25px;border-top-right-radius:25px;border-bottom-left-radius:25px;border-bottom-right-radius:25px\"><!-- wp:column {\"className\":\"zanimljivosti-card\"} -->\n<div class=\"wp-block-column zanimljivosti-card\"><!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\"><em><strong>TikTok algoritam zna bolje od tebe</strong></em></h4>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-medium-font-size\"><em>TikTok može predvidjeti tvoje interese nakon samo<br>nekoliko minuta gledanja. Algoritam analizira čak<br>i to koliko dugo zastaneš na određenom videu.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"zanimljivosti-card\"} -->\n<div class=\"wp-block-column zanimljivosti-card\"><!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\"><strong><em>Prosječan čovjek provede 6+ sati online dnevno</em></strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-medium-font-size\"><em>Od toga gotovo 2,5 sata otpada na društvene mreže.<br>U toku jedne godine to je više od 900 sati -<br>ili cijela 37 dana neprekidnog skrolanja.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"zanimljivosti-card\"} -->\n<div class=\"wp-block-column zanimljivosti-card\"><!-- wp:heading {\"level\":4,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h4 class=\"wp-block-heading has-text-align-center\"><strong><em>YouTube je druga najveća tražilica na svijetu</em></strong></h4>\n<!-- /wp:heading -->\n\n<!-- wp:separator {\"align\":\"center\"} -->\n<hr class=\"wp-block-separator aligncenter has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"medium\"} -->\n<p class=\"has-text-align-center has-medium-font-size\"><em>Odmah iza Googlea — koji, usput, posjeduje YouTube.<br>Više ljudi traži upute i odgovore na YouTubeu<br>nego na Bingu, Yahoou i svim ostalima zajedno.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'Zanimljivosti', '', 'inherit', 'closed', 'closed', '', '44-revision-v1', '', '', '2026-06-02 19:08:40', '2026-06-02 19:08:40', '', 44, 'http://localhost/mywordpress/?p=153', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(154, 1, '2026-06-02 19:08:53', '2026-06-02 19:08:53', '{\"styles\":{\"css\":\":where(.wp-site-blocks *:focus){outline-width:2px;outline-style:solid}\\n/* Hover efekat samo za kartice */\\n/* Hover efekat za dugmad */\\n.wp-block-button__link, \\nbutton, \\n.button,\\n.wp-block-button a {\\n    transition: all 0.2s ease;\\n}\\n\\n.wp-block-button__link:hover, \\nbutton:hover, \\n.button:hover {\\n    transform: scale(1.1);\\n  \\n}\\n\\n/* Hover efekat za kartice */\\n.card-box {\\n    transition: transform 0.3s ease, box-shadow 0.3s ease;\\n    border-radius: 16px;\\n}\\n\\n.card-box:hover {\\n    transform: translateY(-5px);\\n    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.15);\\n}\\n\\n/* Hover efekat za meni - podvla\\u010denje */\\n.main-navigation a, \\n.wp-block-navigation a {\\n    position: relative;\\n    text-decoration: none;\\n    transition: all 0.3s ease;\\n}\\n\\n/* Efekat podvla\\u010denja - linija dolazi ispod teksta */\\n.main-navigation a::after,\\n.wp-block-navigation a::after {\\n    content: \'\';\\n    position: absolute;\\n    bottom: -5px;\\n    left: 0;\\n    width: 0;\\n    height: 2px;\\n    background-color: #888888;\\n    transition: width 0.3s ease;\\n}\\n\\n/* Na hover - linija se razvla\\u010di */\\n.main-navigation a:hover::after,\\n.wp-block-navigation a:hover::after {\\n    width: 100%;\\n}\\n\\n/* Blago podizanje teksta na hover */\\n.main-navigation a:hover,\\n.wp-block-navigation a:hover {\\n    transform: translateY(-2px);\\n}\\n\\n/* 1. GRAYSCALE TABELA - \\u010dist, profesionalan izgled */\\ntable {\\n    width: 100%;\\n    border-collapse: separate;\\n    border-spacing: 0;\\n    border-radius: 20px;\\n    overflow: hidden;\\n    box-shadow: 0 10px 25px rgba(0,0,0,0.08);\\n}\\n\\n/* Zaglavlje tabele - tamno sivo */\\nth {\\n    background: linear-gradient(135deg, #2d2d2d 0%, #4a4a4a 100%);\\n    color: #ffffff;\\n    padding: 18px 16px;\\n    font-size: 1rem;\\n    font-weight: 600;\\n    text-transform: uppercase;\\n    letter-spacing: 1px;\\n}\\n\\n/* \\u0106elije tabele */\\ntd {\\n    padding: 14px 16px;\\n    background-color: #ffffff;\\n    border-bottom: 1px solid #e5e5e5;\\n    color: #333333;\\n}\\n\\n/* Zadnji red - bez bordera */\\ntr:last-child td {\\n    border-bottom: none;\\n}\\n\\n/* Hover efekat na red - svijetlo siva */\\ntbody tr:hover td {\\n    background-color: #f5f5f5;\\n}\\n\\n/* Prva kolona - podebljana */\\ntd:first-child, th:first-child {\\n    font-weight: 600;\\n    border-right: 2px solid #e5e5e5;\\n}\\n\\n/* Naizmjeni\\u010dne boje redova */\\ntbody tr:nth-child(even) td {\\n    background-color: #fafafa;\\n}\\n\\ntbody tr:nth-child(even):hover td {\\n    background-color: #f0f0f0;\\n}\\n\\n/* 2. FADE IN EFEKAT - popravljen, bez bagova */\\nbody {\\n    animation: fadeIn 0.5s ease-out;\\n}\\n\\n@keyframes fadeIn {\\n    0% {\\n        opacity: 0;\\n    }\\n    100% {\\n        opacity: 1;\\n    }\\n}\\n\\n/* 3. PREMIUM DUGMAD - grayscale verzija */\\n.wp-block-button__link, \\nbutton, \\n.button {\\n    transition: all 0.25s ease;\\n    position: relative;\\n    overflow: hidden;\\n    background-color: #4a4a4a !important;\\n    color: #ffffff !important;\\n    border-radius: 8px;\\n}\\n\\n.wp-block-button__link:hover, \\nbutton:hover, \\n.button:hover {\\n    transform: translateY(-2px);\\n    box-shadow: 0 8px 20px rgba(0,0,0,0.15);\\n    background-color: #333333 !important;\\n}\\n\\n/* Sjaj efekat na dugmad */\\n.wp-block-button__link::before,\\nbutton::before {\\n    content: \'\';\\n    position: absolute;\\n    top: 0;\\n    left: -100%;\\n    width: 100%;\\n    height: 100%;\\n    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);\\n    transition: left 0.4s ease;\\n}\\n\\n.wp-block-button__link:hover::before,\\nbutton:hover::before {\\n    left: 100%;\\n}\\n\\n/* ========== SAMO ZA STRANICU ZANIMLJIVOSTI ========== */\\n\\n/* Kontejner za sve kartice */\\n.zanimljivosti-grid {\\n    display: grid;\\n    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));\\n    gap: 30px;\\n    margin: 40px 0;\\n}\\n\\n/* Kartica - grayscale stil */\\n.zanimljivosti-card {\\n    background: #ffffff;\\n    border-radius: 24px;\\n    padding: 28px;\\n    box-shadow: 0 5px 15px rgba(0,0,0,0.05);\\n    transition: all 0.3s ease;\\n    border: 1px solid #e8e8e8;\\n}\\n\\n.zanimljivosti-card:hover {\\n    transform: translateY(-8px);\\n    box-shadow: 0 20px 35px rgba(0,0,0,0.1);\\n}\\n\\n/* Naslov kartice */\\n.zanimljivosti-card h3 {\\n    font-size: 1.5rem;\\n    font-weight: 700;\\n    margin-bottom: 16px;\\n    color: #1a1a1a;\\n    border-left: 4px solid #888888;\\n    padding-left: 16px;\\n}\\n\\n/* Tekst kartice */\\n.zanimljivosti-card p {\\n    font-size: 1rem;\\n    line-height: 1.6;\\n    color: #3a3a3a;\\n    margin: 0;\\n}\\n\\n/* Broj ili ikonica na kartici */\\n.zanimljivosti-number {\\n    display: inline-block;\\n    font-size: 2.5rem;\\n    font-weight: 800;\\n    color: #cccccc;\\n    margin-bottom: 12px;\\n    letter-spacing: -2px;\\n}\\n\\n/* Sekcija naslov (izme\\u0111u grupa kartica) */\\n.zanimljivosti-section-title {\\n    font-size: 2rem;\\n    font-weight: 700;\\n    margin: 50px 0 25px 0;\\n    padding-bottom: 12px;\\n    border-bottom: 2px solid #e0e0e0;\\n    color: #222222;\\n}\\n\\n/* Citat / istaknuti tekst */\\n.zanimljivosti-highlight {\\n    background: #f5f5f5;\\n    padding: 24px 32px;\\n    border-radius: 20px;\\n    font-style: italic;\\n    font-size: 1.1rem;\\n    color: #333;\\n    border-left: 4px solid #888888;\\n    margin: 30px 0;\\n}\\n\\n/* Statistika - veliki brojevi */\\n.zanimljivosti-stat {\\n    display: inline-block;\\n    font-size: 3rem;\\n    font-weight: 800;\\n    color: #4a4a4a;\\n    line-height: 1;\\n}\\n\\n/* Dugme na kartici */\\n.zanimljivosti-btn {\\n    display: inline-block;\\n    margin-top: 20px;\\n    padding: 10px 20px;\\n    background: #4a4a4a;\\n    color: white;\\n    border-radius: 30px;\\n    font-size: 0.85rem;\\n    text-decoration: none;\\n    transition: all 0.25s ease;\\n}\\n\\n.zanimljivosti-btn:hover {\\n    background: #2a2a2a;\\n    transform: translateX(5px);\\n}\\n/* Pozadina za grid kontejner */\\n.zanimljivosti-grid {\\n    background-color: #f5f5f5;\\n    padding: 30px;\\n    border-radius: 24px;\\n}\\n\\n/* Kartice - ista pozadina kao grid */\\n.zanimljivosti-card {\\n    background-color: #f5f5f5;\\n    border: 1px solid #e0e0e0;\\n}\\n\\n/* Ako \\u017eeli\\u0161 da se razlikuju na hover */\\n.zanimljivosti-card:hover {\\n    background-color: #ffffff;\\n    border-color: #cccccc;\\n}\"},\"isGlobalStylesUserThemeJSON\":true,\"version\":3}', 'Custom Styles', '', 'inherit', 'closed', 'closed', '', '99-revision-v1', '', '', '2026-06-02 19:08:53', '2026-06-02 19:08:53', '', 99, 'http://localhost/mywordpress/?p=154', 0, 'revision', '', 0),
