r:hover td {\\n    background-color: #f5f5f5;\\n}\\n\\ntd:first-child, th:first-child {\\n    font-weight: 600;\\n    border-right: 2px solid #e5e5e5;\\n}\\n\\ntbody tr:nth-child(even) td {\\n    background-color: #fafafa;\\n}\\n\\ntbody tr:nth-child(even):hover td {\\n    background-color: #f0f0f0;\\n}\\n\\n/* FADE IN EFEKAT */\\nbody {\\n    animation: fadeIn 0.5s ease-out;\\n}\\n\\n@keyframes fadeIn {\\n    0% { opacity: 0; }\\n    100% { opacity: 1; }\\n}\\n\\n/* PREMIUM DUGMAD - grayscale */\\n.wp-block-button__link, \\nbutton, \\n.button {\\n    transition: all 0.25s ease;\\n    position: relative;\\n    overflow: hidden;\\n    background-color: #4a4a4a !important;\\n    color: #ffffff !important;\\n    border-radius: 8px;\\n}\\n\\n.wp-block-button__link:hover, \\nbutton:hover, \\n.button:hover {\\n    transform: translateY(-2px);\\n    box-shadow: 0 8px 20px rgba(0,0,0,0.15);\\n    background-color: #333333 !important;\\n}\\n\\n.wp-block-button__link::before,\\nbutton::before {\\n    content: \'\';\\n    position: absolute;\\n    top: 0;\\n    left: -100%;\\n    width: 100%;\\n    height: 100%;\\n    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);\\n    transition: left 0.4s ease;\\n}\\n\\n.wp-block-button__link:hover::before,\\nbutton:hover::before {\\n    left: 100%;\\n}\\n\\n/* ========== STRANICA ZANIMLJIVOSTI - BRUTALNA POZADINA ========== */\\n\\n/* Grid kontejner - brutalna pozadina */\\n.zanimljivosti-grid {\\n    display: grid;\\n    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));\\n    gap: 30px;\\n    margin: 40px 0;\\n    background: radial-gradient(circle at 20% 30%, #1a1a2e, #16213e, #0f0f1a);\\n    padding: 50px 40px;\\n    border-radius: 48px;\\n    position: relative;\\n    box-shadow: 0 25px 50px -12px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.05);\\n}\\n\\n/* \\u0160um efekat */\\n.zanimljivosti-grid::before {\\n    content: \'\';\\n    position: absolute;\\n    top: 0;\\n    left: 0;\\n    width: 100%;\\n    height: 100%;\\n    background-image: url(\\\"data:image/svg+xml,%3Csvg viewBox=\'0 0 200 200\' xmlns=\'http://www.w3.org/2000/svg\'%3E%3Cfilter id=\'noise\'%3E%3CfeTurbulence type=\'fractalNoise\' baseFrequency=\'0.65\' numOctaves=\'3\' stitchTiles=\'stitch\'/%3E%3C/filter%3E%3Crect width=\'100%25\' height=\'100%25\' filter=\'url(%23noise)\' opacity=\'0.04\'/%3E%3C/svg%3E\\\");\\n    pointer-events: none;\\n    border-radius: 48px;\\n}\\n\\n/* Kartice - ista pozadina (transparentne) */\\n.zanimljivosti-card {\\n    background: rgba(255, 255, 255, 0.03);\\n    backdrop-filter: blur(2px);\\n    border-radius: 24px;\\n    padding: 28px;\\n    transition: all 0.3s cubic-bezier(0.2, 0.9, 0.4, 1.1);\\n    border: 1px solid rgba(255, 255, 255, 0.08);\\n}\\n\\n.zanimljivosti-card:hover {\\n    transform: translateY(-8px) scale(1.01);\\n    background: rgba(255, 255, 255, 0.06);\\n    border-color: rgba(255, 255, 255, 0.2);\\n    box-shadow: 0 20px 40px rgba(0,0,0,0.3);\\n}\\n\\n/* Naslov kartice */\\n.zanimljivosti-card h3 {\\n    font-size: 1.5rem;\\n    font-weight: 700;\\n    margin-bottom: 16px;\\n    color: #ffffff;\\n    border-left: 4px solid #00A8B5;\\n    padding-left: 16px;\\n}\\n\\n/* Tekst kartice */\\n.zanimljivosti-card p {\\n    font-size: 1rem;\\n    line-height: 1.6;\\n    color: #d0d0d0;\\n    margin: 0;\\n}\\n\\n/* Sekcija naslov */\\n.zanimljivosti-section-title {\\n    font-size: 2.2rem;\\n    font-weight: 700;\\n    margin: 50px 0 25px 0;\\n    padding-bottom: 12px;\\n    border-bottom: 2px solid rgba(255,255,255,0.2);\\n    color: #ffffff;\\n    letter-spacing: -0.5px;\\n}\\n\\n/* Istaknuti tekst */\\n.zanimljivosti-highlight {\\n    background: rgba(255,255,255,0.05);\\n    padding: 24px 32px;\\n    border-radius: 24px;\\n    font-style: italic;\\n    font-size: 1.1rem;\\n    color: #e0e0e0;\\n    border-left: 4px solid #00A8B5;\\n    margin: 30px 0;\\n}\\n\\n/* Statistika - veliki brojevi */\\n.zanimljivosti-stat {\\n    display: inline-block;\\n    font-size: 3rem;\\n    font-weight: 800;\\n    color: #00A8B5;\\n    line-height: 1;\\n}\\n\\n/* Broj/ikona */\\n.zanimljivosti-number {\\n    display: inline-block;\\n    font-size: 2.5rem;\\n    font-weight: 800;\\n    color: rgba(255,255,255,0.2);\\n    margin-bottom: 12px;\\n    letter-spacing: -2px;\\n}\"},\"isGlobalStylesUserThemeJSON\":true,\"version\":3}', 'Custom Styles', '', 'inherit', 'closed', 'closed', '', '99-revision-v1', '', '', '2026-06-02 19:14:53', '2026-06-02 19:14:53', '', 99, 'http://localhost/mywordpress/?p=158', 0, 'revision', '', 0),
