r:hover td {\\n    background-color: #f5f5f5;\\n}\\n\\ntd:first-child, th:first-child {\\n    font-weight: 600;\\n    border-right: 2px solid #e5e5e5;\\n}\\n\\ntbody tr:nth-child(even) td {\\n    background-color: #fafafa;\\n}\\n\\ntbody tr:nth-child(even):hover td {\\n    background-color: #f0f0f0;\\n}\\n\\n/* FADE IN EFEKAT */\\nbody {\\n    animation: fadeIn 0.5s ease-out;\\n}\\n\\n@keyframes fadeIn {\\n    0% { opacity: 0; }\\n    100% { opacity: 1; }\\n}\\n\\n/* PREMIUM DUGMAD - grayscale */\\n.wp-block-button__link, \\nbutton, \\n.button {\\n    transition: all 0.25s ease;\\n    position: relative;\\n    overflow: hidden;\\n    background-color: #4a4a4a !important;\\n    color: #ffffff !important;\\n    border-radius: 8px;\\n}\\n\\n.wp-block-button__link:hover, \\nbutton:hover, \\n.button:hover {\\n    transform: translateY(-2px);\\n    box-shadow: 0 8px 20px rgba(0,0,0,0.15);\\n    background-color: #333333 !important;\\n}\\n\\n.wp-block-button__link::before,\\nbutton::before {\\n    content: \'\';\\n    position: absolute;\\n    top: 0;\\n    left: -100%;\\n    width: 100%;\\n    height: 100%;\\n    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);\\n    transition: left 0.4s ease;\\n}\\n\\n.wp-block-button__link:hover::before,\\nbutton:hover::before {\\n    left: 100%;\\n}\\n\\n/* ========== ZANIMLJIVOSTI - STAKLO EFEKAT (BRUTALNO) ========== */\\n\\n/* Grid kontejner - mra\\u010dni brutalni gradijent */\\n.zanimljivosti-grid {\\n    display: grid;\\n    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));\\n    gap: 30px;\\n    margin: 40px 0;\\n    background: radial-gradient(circle at 30% 10%, #0f0c29, #302b63, #24243e);\\n    padding: 60px 45px;\\n    border-radius: 60px;\\n    position: relative;\\n    box-shadow: 0 30px 60px rgba(0,0,0,0.4), inset 0 1px 0 rgba(255,255,255,0.1);\\n}\\n\\n/* \\u0160um efekat - brutalno */\\n.zanimljivosti-grid::before {\\n    content: \'\';\\n    position: absolute;\\n    top: 0;\\n    left: 0;\\n    width: 100%;\\n    height: 100%;\\n    background-image: url(\\\"data:image/svg+xml,%3Csvg viewBox=\'0 0 200 200\' xmlns=\'http://www.w3.org/2000/svg\'%3E%3Cfilter id=\'noise\'%3E%3CfeTurbulence type=\'fractalNoise\' baseFrequency=\'0.7\' numOctaves=\'4\' stitchTiles=\'stitch\'/%3E%3C/filter%3E%3Crect width=\'100%25\' height=\'100%25\' filter=\'url(%23noise)\' opacity=\'0.05\'/%3E%3C/svg%3E\\\");\\n    pointer-events: none;\\n    border-radius: 60px;\\n}\\n\\n/* Kartice - STAKLO EFEKAT (providne, zamu\\u0107ene) */\\n.zanimljivosti-card {\\n    background: rgba(20, 20, 40, 0.45);\\n    backdrop-filter: blur(12px);\\n    border-radius: 32px;\\n    padding: 32px;\\n    transition: all 0.4s cubic-bezier(0.2, 0.9, 0.4, 1.1);\\n    border: 1px solid rgba(255, 255, 255, 0.2);\\n    box-shadow: 0 8px 20px rgba(0,0,0,0.2);\\n}\\n\\n.zanimljivosti-card:hover {\\n    transform: translateY(-12px) scale(1.02);\\n    background: rgba(30, 30, 55, 0.6);\\n    border-color: rgba(255, 255, 255, 0.4);\\n    box-shadow: 0 30px 50px rgba(0,0,0,0.4);\\n}\\n\\n/* Naslov kartice - bijeli sa sjajem */\\n.zanimljivosti-card h3 {\\n    font-size: 1.5rem;\\n    font-weight: 700;\\n    margin-bottom: 16px;\\n    color: #ffffff;\\n    border-left: 4px solid #00d4ff;\\n    padding-left: 18px;\\n    text-shadow: 0 2px 5px rgba(0,0,0,0.3);\\n}\\n\\n/* Tekst kartice - svijetli */\\n.zanimljivosti-card p {\\n    font-size: 1rem;\\n    line-height: 1.6;\\n    color: rgba(255, 255, 255, 0.85);\\n    margin: 0;\\n}\\n\\n/* Sekcija naslov - bijeli sa neon efektom */\\n.zanimljivosti-section-title {\\n    font-size: 2.3rem;\\n    font-weight: 800;\\n    margin: 55px 0 30px 0;\\n    padding-bottom: 15px;\\n    border-bottom: 2px solid rgba(0, 212, 255, 0.5);\\n    color: #ffffff;\\n    letter-spacing: -0.5px;\\n    text-shadow: 0 0 10px rgba(0,212,255,0.3);\\n}\\n\\n/* Istaknuti tekst - staklo */\\n.zanimljivosti-highlight {\\n    background: rgba(255,255,255,0.08);\\n    backdrop-filter: blur(8px);\\n    padding: 28px 35px;\\n    border-radius: 32px;\\n    font-style: italic;\\n    font-size: 1.15rem;\\n    color: #ffffff;\\n    border-left: 4px solid #00d4ff;\\n    margin: 35px 0;\\n}\\n\\n/* Statistika - neon */\\n.zanimljivosti-stat {\\n    display: inline-block;\\n    font-size: 3.2rem;\\n    font-weight: 800;\\n    background: linear-gradient(135deg, #ffffff, #00d4ff);\\n    -webkit-background-clip: text;\\n    background-clip: text;\\n    color: transparent;\\n    line-height: 1;\\n}\\n\\n/* Broj/ikona */\\n.zanimljivosti-number {\\n    display: inline-block;\\n    font-size: 2.5rem;\\n    font-weight: 800;\\n    color: rgba(255,255,255,0.25);\\n    margin-bottom: 12px;\\n    letter-spacing: -3px;\\n}\"},\"isGlobalStylesUserThemeJSON\":true,\"version\":3}', 'Custom Styles', '', 'inherit', 'closed', 'closed', '', '99-revision-v1', '', '', '2026-06-02 19:27:51', '2026-06-02 19:27:51', '', 99, 'http://localhost/mywordpress/?p=164', 0, 'revision', '', 0),
