r:hover td {\\n    background-color: #f5f5f5;\\n}\\n\\ntd:first-child, th:first-child {\\n    font-weight: 600;\\n    border-right: 2px solid #e5e5e5;\\n}\\n\\ntbody tr:nth-child(even) td {\\n    background-color: #fafafa;\\n}\\n\\ntbody tr:nth-child(even):hover td {\\n    background-color: #f0f0f0;\\n}\\n\\n/* FADE IN EFEKAT */\\nbody {\\n    animation: fadeIn 0.5s ease-out;\\n}\\n\\n@keyframes fadeIn {\\n    0% { opacity: 0; }\\n    100% { opacity: 1; }\\n}\\n\\n/* PREMIUM DUGMAD - grayscale */\\n.wp-block-button__link, \\nbutton, \\n.button {\\n    transition: all 0.25s ease;\\n    position: relative;\\n    overflow: hidden;\\n    background-color: #4a4a4a !important;\\n    color: #ffffff !important;\\n    border-radius: 8px;\\n}\\n\\n.wp-block-button__link:hover, \\nbutton:hover, \\n.button:hover {\\n    transform: translateY(-2px);\\n    box-shadow: 0 8px 20px rgba(0,0,0,0.15);\\n    background-color: #333333 !important;\\n}\\n\\n.wp-block-button__link::before,\\nbutton::before {\\n    content: \'\';\\n    position: absolute;\\n    top: 0;\\n    left: -100%;\\n    width: 100%;\\n    height: 100%;\\n    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);\\n    transition: left 0.4s ease;\\n}\\n\\n.wp-block-button__link:hover::before,\\nbutton:hover::before {\\n    left: 100%;\\n}\\n\\n/* ========== ZANIMLJIVOSTI - STAKLO (GRAYSCALE) ========== */\\n\\n/* Grid kontejner - svijetli sivi gradijent */\\n.zanimljivosti-grid {\\n    display: grid;\\n    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));\\n    gap: 30px;\\n    margin: 40px 0;\\n    background: linear-gradient(135deg, #ececec 0%, #dfdfdf 50%, #d2d2d2 100%);\\n    padding: 50px 40px;\\n    border-radius: 48px;\\n    position: relative;\\n    box-shadow: 0 15px 35px rgba(0,0,0,0.05);\\n}\\n\\n/* Kartice - STAKLO EFEKAT (providne, zamu\\u0107ene) */\\n.zanimljivosti-card {\\n    background: rgba(255, 255, 255, 0.45);\\n    backdrop-filter: blur(12px);\\n    border-radius: 32px;\\n    padding: 28px;\\n    transition: all 0.3s ease;\\n    border: 1px solid rgba(255, 255, 255, 0.7);\\n    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.05);\\n}\\n\\n.zanimljivosti-card:hover {\\n    transform: translateY(-8px);\\n    background: rgba(255, 255, 255, 0.65);\\n    border-color: rgba(255, 255, 255, 0.9);\\n    box-shadow: 0 20px 35px rgba(0, 0, 0, 0.1);\\n}\\n\\n/* Naslov kartice - taman, vidljiv */\\n.zanimljivosti-card h3 {\\n    font-size: 1.5rem;\\n    font-weight: 700;\\n    margin-bottom: 16px;\\n    color: #1a1a1a;\\n    border-left: 4px solid #888888;\\n    padding-left: 16px;\\n}\\n\\n/* Tekst kartice - taman */\\n.zanimljivosti-card p {\\n    font-size: 1rem;\\n    line-height: 1.6;\\n    color: #2c2c2c;\\n    margin: 0;\\n}\\n\\n/* Sekcija naslov - taman */\\n.zanimljivosti-section-title {\\n    font-size: 2rem;\\n    font-weight: 700;\\n    margin: 50px 0 25px 0;\\n    padding-bottom: 12px;\\n    border-bottom: 2px solid #aaaaaa;\\n    color: #1a1a1a;\\n    letter-spacing: -0.5px;\\n}\\n\\n/* Istaknuti tekst - staklo */\\n.zanimljivosti-highlight {\\n    background: rgba(255, 255, 255, 0.4);\\n    backdrop-filter: blur(5px);\\n    padding: 24px 32px;\\n    border-radius: 28px;\\n    font-style: italic;\\n    font-size: 1.1rem;\\n    color: #1a1a1a;\\n    border-left: 4px solid #888888;\\n    margin: 30px 0;\\n}\\n\\n/* Statistika */\\n.zanimljivosti-stat {\\n    display: inline-block;\\n    font-size: 2.8rem;\\n    font-weight: 800;\\n    color: #4a4a4a;\\n    line-height: 1;\\n}\\n\\n/* Broj/ikona */\\n.zanimljivosti-number {\\n    display: inline-block;\\n    font-size: 2.2rem;\\n    font-weight: 800;\\n    color: #bbbbbb;\\n    margin-bottom: 12px;\\n    letter-spacing: -2px;\\n}\"},\"isGlobalStylesUserThemeJSON\":true,\"version\":3}', 'Custom Styles', '', 'inherit', 'closed', 'closed', '', '99-revision-v1', '', '', '2026-06-02 19:32:26', '2026-06-02 19:32:26', '', 99, 'http://localhost/mywordpress/?p=166', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
