n\\ntbody tr:hover td {\\n    background-color: #f5f5f5;\\n}\\n\\ntd:first-child, th:first-child {\\n    font-weight: 600;\\n    border-right: 2px solid #e5e5e5;\\n}\\n\\ntbody tr:nth-child(even) td {\\n    background-color: #fafafa;\\n}\\n\\ntbody tr:nth-child(even):hover td {\\n    background-color: #f0f0f0;\\n}\\n\\n/* FADE IN EFEKAT */\\nbody {\\n    animation: fadeIn 0.5s ease-out;\\n}\\n\\n@keyframes fadeIn {\\n    0% { opacity: 0; }\\n    100% { opacity: 1; }\\n}\\n\\n/* PREMIUM DUGMAD - grayscale */\\n.wp-block-button__link, \\nbutton, \\n.button {\\n    transition: all 0.25s ease;\\n    position: relative;\\n    overflow: hidden;\\n    background-color: #4a4a4a !important;\\n    color: #ffffff !important;\\n    border-radius: 8px;\\n}\\n\\n.wp-block-button__link:hover, \\nbutton:hover, \\n.button:hover {\\n    transform: translateY(-2px);\\n    box-shadow: 0 8px 20px rgba(0,0,0,0.15);\\n    background-color: #333333 !important;\\n}\\n\\n.wp-block-button__link::before,\\nbutton::before {\\n    content: \'\';\\n    position: absolute;\\n    top: 0;\\n    left: -100%;\\n    width: 100%;\\n    height: 100%;\\n    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);\\n    transition: left 0.4s ease;\\n}\\n\\n.wp-block-button__link:hover::before,\\nbutton:hover::before {\\n    left: 100%;\\n}\\n\\n/* ========== STRANICA ZANIMLJIVOSTI (staklo, grayscale) ========== */\\n.zanimljivosti-grid {\\n    display: grid;\\n    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));\\n    gap: 30px;\\n    margin: 40px 0;\\n    background: linear-gradient(135deg, #ececec 0%, #dfdfdf 50%, #d2d2d2 100%);\\n    padding: 50px 40px;\\n    border-radius: 48px;\\n    position: relative;\\n    box-shadow: 0 15px 35px rgba(0,0,0,0.05);\\n}\\n\\n.zanimljivosti-card {\\n    background: rgba(255, 255, 255, 0.45);\\n    backdrop-filter: blur(12px);\\n    border-radius: 32px;\\n    padding: 28px;\\n    transition: all 0.3s ease;\\n    border: 1px solid rgba(255, 255, 255, 0.7);\\n    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.05);\\n}\\n\\n.zanimljivosti-card:hover {\\n    transform: translateY(-8px);\\n    background: rgba(255, 255, 255, 0.65);\\n    border-color: rgba(255, 255, 255, 0.9);\\n    box-shadow: 0 20px 35px rgba(0, 0, 0, 0.1);\\n}\\n\\n.zanimljivosti-card h3 {\\n    font-size: 1.5rem;\\n    font-weight: 700;\\n    margin-bottom: 16px;\\n    color: #1a1a1a;\\n    border-left: 4px solid #888888;\\n    padding-left: 16px;\\n}\\n\\n.zanimljivosti-card p {\\n    font-size: 1rem;\\n    line-height: 1.6;\\n    color: #2c2c2c;\\n    margin: 0;\\n}\\n\\n.zanimljivosti-section-title {\\n    font-size: 2rem;\\n    font-weight: 700;\\n    margin: 50px 0 25px 0;\\n    padding-bottom: 12px;\\n    border-bottom: 2px solid #aaaaaa;\\n    color: #1a1a1a;\\n    letter-spacing: -0.5px;\\n}\\n\\n.zanimljivosti-highlight {\\n    background: rgba(255, 255, 255, 0.4);\\n    backdrop-filter: blur(5px);\\n    padding: 24px 32px;\\n    border-radius: 28px;\\n    font-style: italic;\\n    font-size: 1.1rem;\\n    color: #1a1a1a;\\n    border-left: 4px solid #888888;\\n    margin: 30px 0;\\n}\\n\\n.zanimljivosti-stat {\\n    display: inline-block;\\n    font-size: 2.8rem;\\n    font-weight: 800;\\n    color: #4a4a4a;\\n    line-height: 1;\\n}\\n\\n.zanimljivosti-number {\\n    display: inline-block;\\n    font-size: 2.2rem;\\n    font-weight: 800;\\n    color: #bbbbbb;\\n    margin-bottom: 12px;\\n    letter-spacing: -2px;\\n}\\n\\n/* ========== STRANICA STATISTIKE (grayscale, staklo) ========== */\\n\\n/* Grid za 4 statistike (brojevi) */\\n.statistike-grid {\\n    display: grid;\\n    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\\n    gap: 25px;\\n    margin: 40px 0;\\n}\\n\\n/* Kartica za pojedina\\u010dnu statistiku */\\n.stat-card {\\n    background: rgba(255, 255, 255, 0.5);\\n    backdrop-filter: blur(8px);\\n    border-radius: 28px;\\n    padding: 28px 20px;\\n    text-align: center;\\n    transition: all 0.3s ease;\\n    border: 1px solid rgba(255, 255, 255, 0.7);\\n    box-shadow: 0 5px 15px rgba(0,0,0,0.03);\\n}\\n\\n.stat-card:hover {\\n    transform: translateY(-6px);\\n    background: rgba(255, 255, 255, 0.7);\\n    border-color: #ffffff;\\n    box-shadow: 0 15px 30px rgba(0,0,0,0.08);\\n}\\n\\n/* Broj (veliki) */\\n.stat-number {\\n    display: block;\\n    font-size: 3.2rem;\\n    font-weight: 800;\\n    color: #2a2a2a;\\n    line-height: 1.1;\\n    margin-bottom: 8px;\\n    letter-spacing: -1px;\\n}\\n\\n/* Opis ispod broja */\\n.stat-label {\\n    display: block;\\n    font-size: 0.95rem;\\n    font-weight: 500;\\n    color: #4a4a4a;\\n    text-transform: uppercase;\\n    letter-spacing: 0.5px;\\n}\\n\\n/* Tamna sekcija (Bosna i Hercegovina) - staklo varijanta */\\n.bih-section {\\n    background: rgba(200, 200, 200, 0.4);\\n    backdrop-filter: blur(8px);\\n    border-radius: 36px;\\n    padding: 40px 35px;\\n    margin: 50px 0;\\n    border: 1px solid rgba(255, 255, 255, 0.6);\\n    text-align: center;\\n    transition: all 0.3s ease;\\n}\\n\\n.bih-section:hover {\\n    background: rgba(200, 200, 200, 0.6);\\n    border-color: rgba(255, 255, 255, 0.8);\\n    box-shadow: 0 15px 30px rgba(0,0,0,0.05);\\n}\\n\\n.bih-section h2 {\\n    font-size: 2rem;\\n    font-weight: 700;\\n    color: #1a1a1a;\\n    margin-bottom: 20px;\\n}\\n\\n.bih-section p {\\n    font-size: 1.1rem;\\n    line-height: 1.5;\\n    color: #2c2c2c;\\n    max-width: 800px;\\n    margin-left: auto;\\n    margin-right: auto;\\n}\\n\\n/* Dugme u tamnoj sekciji (ako nije ve\\u0107 pokriveno globalnim) */\\n.bih-section .wp-block-button__link {\\n    margin-top: 20px;\\n    background-color: #4a4a4a !important;\\n}\"},\"isGlobalStylesUserThemeJSON\":true,\"version\":3}', 'Custom Styles', '', 'inherit', 'closed', 'closed', '', '99-revision-v1', '', '', '2026-06-02 19:37:00', '2026-06-02 19:37:00', '', 99, 'http://localhost/mywordpress/?p=167', 0, 'revision', '', 0),
(168, 1, '2026-06-02 19:46:47', '2026-06-02 19:46:47', '<!-- wp:group {\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\"><!-- wp:group {\"metadata\":{\"name\":\"About\"},\"align\":\"wide\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}},\"border\":{\"radius\":\"16px\"},\"background\":{\"backgroundSize\":\"contain\",\"backgroundRepeat\":\"no-repeat\",\"backgroundPosition\":\"45% 0%\"}},\"backgroundColor\":\"base\",\"fontSize\":\"small\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide has-base-background-color has-background has-small-font-size\" style=\"border-radius:16px;padding-top:var(--wp--preset--spacing--40);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--40);padding-left:var(--wp--preset--spacing--40)\"><!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":\"1.5rem\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"stretch\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:group {\"align\":\"wide\",\"style\":{\"typography\":{\"textTransform\":\"none\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|primary\"}}}},\"textColor\":\"primary\",\"fontSize\":\"small\",\"fontFamily\":\"inter-tight\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"stretch\"}} -->\n<div class=\"wp-block-group alignwide has-primary-color ha