s-text-color has-link-color has-inter-tight-font-family has-small-font-size\" style=\"text-transform:none\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Za samo pet godina, više od milijardu novih korisnika priključilo se globalnoj digitalnoj mreži. Danas internet koristi 5,56 milijardi ljudi – više nego što gleda televiziju.</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"var:preset|spacing|10\"} -->\n<div style=\"height:var(--wp--preset--spacing--10)\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Stats\"},\"align\":\"wide\",\"className\":\"statistike-grid\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide statistike-grid\" style=\"padding-right:0;padding-left:0\"><!-- wp:columns {\"metadata\":{\"name\":\"Stats\"},\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"className\":\"stat-card\"} -->\n<div class=\"wp-block-column stat-card\"><!-- wp:heading {\"level\":3,\"className\":\"stat-number\",\"style\":{\"typography\":{\"textAlign\":\"center\"},\"color\":{\"text\":\"#185fa5\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#185fa5\"}}}},\"fontSize\":\"x-large\"} -->\n<h3 class=\"wp-block-heading has-text-align-center stat-number has-text-color has-link-color has-x-large-font-size\" style=\"color:#185fa5\">5,5+ mlrd</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"stat-label\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center stat-label\">korisnika interneta globalno</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"stat-card\"} -->\n<div class=\"wp-block-column stat-card\"><!-- wp:heading {\"level\":3,\"className\":\"stat-number\",\"style\":{\"typography\":{\"textAlign\":\"center\"},\"color\":{\"text\":\"#185fa5\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#185fa5\"}}}},\"fontSize\":\"x-large\"} -->\n<h3 class=\"wp-block-heading has-text-align-center stat-number has-text-color has-link-color has-x-large-font-size\" style=\"color:#185fa5\">4,6+ milijardi</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"stat-label\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center stat-label\">korisnika društvenih mreža</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"stat-card\"} -->\n<div class=\"wp-block-column stat-card\"><!-- wp:heading {\"level\":3,\"className\":\"stat-number\",\"style\":{\"typography\":{\"textAlign\":\"center\"},\"color\":{\"text\":\"#185fa5\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#185fa5\"}}}},\"fontSize\":\"x-large\"} -->\n<h3 class=\"wp-block-heading has-text-align-center stat-number has-text-color has-link-color has-x-large-font-size\" style=\"color:#185fa5\">6h 30+ min</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"stat-label\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center stat-label\">prosječno dnevno online</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"className\":\"stat-card\"} -->\n<div class=\"wp-block-column stat-card\"><!-- wp:heading {\"level\":3,\"className\":\"stat-number\",\"style\":{\"typography\":{\"textAlign\":\"center\"},\"color\":{\"text\":\"#185fa5\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#185fa5\"}}}},\"fontSize\":\"x-large\"} -->\n<h3 class=\"wp-block-heading has-text-align-center stat-number has-text-color has-link-color has-x-large-font-size\" style=\"color:#185fa5\">+1 mlrd</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"stat-label\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center stat-label\">novih korisnika od 2020.</p>\