lumn --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"var:preset|spacing|40\"} -->\n<div style=\"height:var(--wp--preset--spacing--40)\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|60\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"width\":\"50%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:image {\"id\":85,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"is-style-rounded\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"300px\",\"topRight\":\"300px\",\"bottomLeft\":\"300px\",\"bottomRight\":\"300px\"}}}} -->\n<figure class=\"wp-block-image size-large has-custom-border is-style-rounded\"><img src=\"http://localhost/mywordpress/wp-content/uploads/2026/05/collabstr-0vk7hejwlde-unsplash.jpg?w=1024\" alt=\"\" class=\"wp-image-85\" style=\"border-top-left-radius:300px;border-top-right-radius:300px;border-bottom-left-radius:300px;border-bottom-right-radius:300px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"40%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:40%\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\"} -->\n<h3 class=\"wp-block-heading is-style-default\"><strong>TikTok i mladi</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"className\":\"is-style-checkmark-list\",\"style\":{\"typography\":{\"lineHeight\":\"1.75\"}}} -->\n<ul style=\"line-height:1.75\" class=\"wp-block-list is-style-checkmark-list\"><!-- wp:list-item -->\n<li><em>Najbrže rastuća platforma među korisnicima do 24 godine</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Novi format konzumiranja vijesti kroz kratke, viralne videe</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Lokalni kreatori sadržaja grade publiku i van granica BiH</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Platforme poput TikToka mijenjaju i jezik i kulturu mladih</em></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"categories\":[\"text\"],\"patternName\":\"twentytwentyfour/text-feature-grid-3-col\",\"name\":\"Feature grid, 3 columns\"},\"align\":\"full\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"}}},\"backgroundColor\":\"base-2\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-base-2-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"0px\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"className\":\"is-style-asterisk\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center is-style-asterisk\"><strong>Izazovi digitalnog društva</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"0px\",\"style\":{\"layout\":{\"flexSize\":\"1.25rem\",\"selfStretch\":\"fixed\"}}} -->\n<div style=\"height:0px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Visoka penetracija interneta ohrabrujući je podatak, ali ne govori<br>cijelu priču. Iza brojeva kriju se dublje nejednakosti - između<br>generacija, između grada i sela, između onih koji znaju kritički<br>čitati online sadržaj i onih koji ne znaju. BiH se suočava sa<br>izazovima koji nisu jedinstveni, ali imaju lokalni kontekst koji<br>ih čini specifičnima i složenijima za rješavanje.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"var:preset|spacing|40\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div style=\"margin-top:0;margin-bottom:0;height:var(--wp--preset--spacing--40)\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Dezinformacije i lažne vijesti</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Bosanskohercegovački online prostor posebno je ranjiv na dezinformacije zbog fragmentiranog medijskog tržišta, etničkih podjela i slabe medijske regulacije. Lažne vijesti šire se najčešće putem Facebook grupa i WhatsApp poruka, često bez ikakve provjere izvora.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Digitalna pismenost</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Starije generacije i stanovnici ruralnih područja suočavaju se sa značajnim preprekama u korištenju digitalnih usluga. Osnovna pismenost nije dovoljna — potrebno je razumjeti kako funkcionišu algoritmi, prepoznati lažne vijesti i zaštititi svoje podatke.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Zaštita privatnosti</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Većina korisnika u BiH nije svjesna koliko podataka dijeli sa platformama svakodnevno. GDPR regulativa primjenjuje se i u BiH kao dio procesa evropskih integracija, ali svijest građana o pravima na privatnost ostaje zabrinjavajuće niska.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"65px\"} -->\n<div style=\"height:65px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Digitalna nejednakost</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Brzi internet nije ravnomjerno dostupan u svim dijelovima BiH. Razlika između urbanih centara poput Sarajeva, Banja Luke i Mostara i manjih mjesta i sela i dalje je izražena — kako u brzini interneta, tako i u cijeni pristupa.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Govor mržnje online</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Etničke i političke podjele koje postoje u fizičkom prostoru direktno se prenose na digitalni. Istraživanja pokazuju da je BiH jedna od zemalja regije s najvećim udjelom govora mržnje na društvenim mrežama, posebno u periodima izbora i kriza.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">E-uprava i digitalne javne usluge</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Digitalizacija državnih usluga napreduje sporije nego u susjednim zemljama. Građani još uvijek moraju fizički dolaziti po mnoge dokumente i potvrde. Ipak, neke opštine i institucije uvode online usluge, što je korak u pravom smjeru.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->', 'BiH kontekst', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2026-06-03 17:41:18', '2026-06-03 17:41:18', '', 16, 'http://localhost/mywordpress/?p=172', 0, 'revision', '', 0),
(173, 1, '2026-06-03 17:42:12', '2026-06-03 17:42:12', '<!-- wp:group {\"metadata\":{\"categories\":[\"text\"],\"patternName\":\"twentytwentyfour/text-alternating-images\",\"name\":\"Text with alternating images\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\"><!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"className\":\"is-style-asterisk\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center is-style-asterisk\"><strong>Društvene mreže kao novi javni prostor</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null},\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>U BiH digitalne platforme nisu samo zabava - one su postale mjesto vijesti,<br>politike, dijaspore i svakodnevne komunikacije.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null},\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"var:preset|spacing|40\"} -->\n<div style=\"height:var(--wp--preset--spacing--40)\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|60\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"40%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:40%\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\"} -->\n<h3 class=\"wp-block-heading is-style-default\"><strong>Facebook dominira</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"className\":\"is-style-checkmark-list\",\"style\":{\"typography\":{\"lineHeight\":\"1.75\"}}} -->\n<ul style=\"line-height:1.75\" class=\"wp-block-list is-style-checkmark-list\"><!-- wp:list-item -->\n<li><em>Najpopularnija platforma kod 25–45 godina</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Glavno mjesto javne rasprave i vijesti</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Ključni kanal za dijasporu</em></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:image {\"id\":84,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"is-style-rounded\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"300px\",\"topRight\":\"300px\",\"bottomLeft\":\"300px\",\"bottomRight\":\"300px\"}}}} -->\n<figure class=\"wp-block-image size-large has-custom-border is-style-rounded\"><img src=\"http://localhost/mywordpress/wp-content/uploads/2026/05/brett-jordan-eefrxcpixna-unsplash.jpg?w=1024\" alt=\"\" class=\"wp-image-84\" style=\"border-top-left-radius:300px;border-top-right-radius:300px;border-bottom-left-radius:300px;border-bottom-right-radius:300px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"var:preset|spacing|40\"} -->\n<div style=\"height:var(--wp--preset--spacing--40)\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|60\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"width\":\"50%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:image {\"id\":85,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"is-style-rounded\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"300px\",\"topRight\":\"300px\",\"bottomLeft\":\"300px\",\"bottomRight\":\"300px\"}}}} -->\n<figure class=\"wp-block-image size-large has-custom-border is-style-rounded\"><img src=\"http://localhost/mywordpress/wp-content/uploads/2026/05/collabstr-0vk7hejwlde-unsplash.jpg?w=1024\" alt=\"\" class=\"wp-image-85\" style=\"border-top-left-radius:300px;border-top-right-radius:300px;border-bottom-left-radius:300px;border-bottom-right-radius:300px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"40%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:40%\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\"} -->\n<h3 class=\"wp-block-heading is-style-default\"><strong>TikTok i mladi</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"className\":\"is-style-checkmark-list\",\"style\":{\"typography\":{\"lineHeight\":\"1.75\"}}} -->\n<ul style=\"line-height:1.75\" class=\"wp-block-list is-style-checkmark-list\"><!-- wp:list-item -->\n<li><em>Najbrže rastuća platforma među korisnicima do 24 godine</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Novi format konzumiranja vijesti kroz kratke, viralne videe</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Lokalni kreatori sadržaja grade publiku i van granica BiH</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Platforme poput TikToka mijenjaju i jezik i kulturu mladih</em></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"categories\":[\"text\"],\"patternName\":\"twentytwentyfour/text-feature-grid-3-col\",\"name\":\"Feature grid, 3 columns\"},\"align\":\"full\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"}}},\"backgroundColor\":\"base-2\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-base-2-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"0px\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"className\":\"is-style-asterisk\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center is-style-asterisk\"><strong>Izazovi digitalnog društva</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"0px\",\"style\":{\"layout\":{\"flexSize\":\"1.25rem\",\"selfStretch\":\"fixed\"}}} -->\n<div style=\"height:0px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Visoka penetracija interneta ohrabrujući je podatak, ali ne govori<br>cijelu priču. Iza brojeva kriju se dublje nejednakosti - između<br>generacija, između grada i sela, između onih koji znaju kritički<br>čitati online sadržaj i onih koji ne znaju. BiH se suočava sa<br>izazovima koji nisu jedinstveni, ali imaju lokalni kontekst koji<br>ih čini specifičnima i složenijima za rješavanje.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"var:preset|spacing|40\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div style=\"margin-top:0;margin-bottom:0;height:var(--wp--preset--spacing--40)\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Dezinformacije i lažne vijesti</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Bosanskohercegovački online prostor posebno je ranjiv na dezinformacije zbog fragmentiranog medijskog tržišta, etničkih podjela i slabe medijske regulacije. Lažne vijesti šire se najčešće putem Facebook grupa i WhatsApp poruka, često bez ikakve provjere izvora.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Digitalna pismenost</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Starije generacije i stanovnici ruralnih područja suočavaju se sa značajnim preprekama u korištenju digitalnih usluga. Osnovna pismenost nije dovoljna - potrebno je razumjeti kako funkcionišu algoritmi, prepoznati lažne vijesti i zaštititi svoje podatke.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Zaštita privatnosti</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Većina korisnika u BiH nije svjesna koliko podataka dijeli sa platformama svakodnevno. GDPR regulativa primjenjuje se i u BiH kao dio procesa evropskih integracija, ali svijest građana o pravima na privatnost ostaje zabrinjavajuće niska.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"65px\"} -->\n<div style=\"height:65px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Digitalna nejednakost</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Brzi internet nije ravnomjerno dostupan u svim dijelovima BiH. Razlika između urbanih centara poput Sarajeva, Banja Luke i Mostara i manjih mjesta i sela i dalje je izražena - kako u brzini interneta, tako i u cijeni pristupa.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Govor mržnje online</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Etničke i političke podjele koje postoje u fizičkom prostoru direktno se prenose na digitalni. Istraživanja pokazuju da je BiH jedna od zemalja regije s najvećim udjelom govora mržnje na društvenim mrežama, posebno u periodima izbora i kriza.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">E-uprava i digitalne javne usluge</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Digitalizacija državnih usluga napreduje sporije nego u susjednim zemljama. Građani još uvijek moraju fizički dolaziti po mnoge dokumente i potvrde. Ipak, neke opštine i institucije uvode online usluge, što je korak u pravom smjeru.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->', 'BiH kontekst', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2026-06-03 17:42:12', '2026-06-03 17:42:12', '', 16, 'http://localhost/mywordpress/?p=173', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(174, 1, '2026-06-03 17:42:30', '2026-06-03 17:42:30', '<!-- wp:group {\"metadata\":{\"categories\":[\"text\"],\"patternName\":\"twentytwentyfour/text-alternating-images\",\"name\":\"Text with alternating images\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\"><!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"className\":\"is-style-asterisk\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center is-style-asterisk\"><strong>Društvene mreže kao novi javni prostor</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null},\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>U BiH digitalne platforme nisu samo zabava - one su postale mjesto vijesti,<br>politike, dijaspore i svakodnevne komunikacije.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null},\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"var:preset|spacing|40\"} -->\n<div style=\"height:var(--wp--preset--spacing--40)\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|60\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"40%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:40%\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\"} -->\n<h3 class=\"wp-block-heading is-style-default\"><strong>Facebook dominira</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"className\":\"is-style-checkmark-list\",\"style\":{\"typography\":{\"lineHeight\":\"1.75\"}}} -->\n<ul style=\"line-height:1.75\" class=\"wp-block-list is-style-checkmark-list\"><!-- wp:list-item -->\n<li><em>Najpopularnija platforma kod 25 - 45 godina</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Glavno mjesto javne rasprave i vijesti</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Ključni kanal za dijasporu</em></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:image {\"id\":84,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"is-style-rounded\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"300px\",\"topRight\":\"300px\",\"bottomLeft\":\"300px\",\"bottomRight\":\"300px\"}}}} -->\n<figure class=\"wp-block-image size-large has-custom-border is-style-rounded\"><img src=\"http://localhost/mywordpress/wp-content/uploads/2026/05/brett-jordan-eefrxcpixna-unsplash.jpg?w=1024\" alt=\"\" class=\"wp-image-84\" style=\"border-top-left-radius:300px;border-top-right-radius:300px;border-bottom-left-radius:300px;border-bottom-right-radius:300px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"var:preset|spacing|40\"} -->\n<div style=\"height:var(--wp--preset--spacing--40)\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|60\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"width\":\"50%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:image {\"id\":85,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"is-style-rounded\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"300px\",\"topRight\":\"300px\",\"bottomLeft\":\"300px\",\"bottomRight\":\"300px\"}}}} -->\n<figure class=\"wp-block-image size-large has-custom-border is-style-rounded\"><img src=\"http://localhost/mywordpress/wp-content/uploads/2026/05/collabstr-0vk7hejwlde-unsplash.jpg?w=1024\" alt=\"\" class=\"wp-image-85\" style=\"border-top-left-radius:300px;border-top-right-radius:300px;border-bottom-left-radius:300px;border-bottom-right-radius:300px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"40%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:40%\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\"} -->\n<h3 class=\"wp-block-heading is-style-default\"><strong>TikTok i mladi</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"className\":\"is-style-checkmark-list\",\"style\":{\"typography\":{\"lineHeight\":\"1.75\"}}} -->\n<ul style=\"line-height:1.75\" class=\"wp-block-list is-style-checkmark-list\"><!-- wp:list-item -->\n<li><em>Najbrže rastuća platforma među korisnicima do 24 godine</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Novi format konzumiranja vijesti kroz kratke, viralne videe</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Lokalni kreatori sadržaja grade publiku i van granica BiH</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Platforme poput TikToka mijenjaju i jezik i kulturu mladih</em></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"categories\":[\"text\"],\"patternName\":\"twentytwentyfour/text-feature-grid-3-col\",\"name\":\"Feature grid, 3 columns\"},\"align\":\"full\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"}}},\"backgroundColor\":\"base-2\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-base-2-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"0px\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"className\":\"is-style-asterisk\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center is-style-asterisk\"><strong>Izazovi digitalnog društva</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"0px\",\"style\":{\"layout\":{\"flexSize\":\"1.25rem\",\"selfStretch\":\"fixed\"}}} -->\n<div style=\"height:0px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Visoka penetracija interneta ohrabrujući je podatak, ali ne govori<br>cijelu priču. Iza brojeva kriju se dublje nejednakosti - između<br>generacija, između grada i sela, između onih koji znaju kritički<br>čitati online sadržaj i onih koji ne znaju. BiH se suočava sa<br>izazovima koji nisu jedinstveni, ali imaju lokalni kontekst koji<br>ih čini specifičnima i složenijima za rješavanje.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"var:preset|spacing|40\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div style=\"margin-top:0;margin-bottom:0;height:var(--wp--preset--spacing--40)\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Dezinformacije i lažne vijesti</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Bosanskohercegovački online prostor posebno je ranjiv na dezinformacije zbog fragmentiranog medijskog tržišta, etničkih podjela i slabe medijske regulacije. Lažne vijesti šire se najčešće putem Facebook grupa i WhatsApp poruka, često bez ikakve provjere izvora.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Digitalna pismenost</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Starije generacije i stanovnici ruralnih područja suočavaju se sa značajnim preprekama u korištenju digitalnih usluga. Osnovna pismenost nije dovoljna - potrebno je razumjeti kako funkcionišu algoritmi, prepoznati lažne vijesti i zaštititi svoje podatke.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Zaštita privatnosti</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Većina korisnika u BiH nije svjesna koliko podataka dijeli sa platformama svakodnevno. GDPR regulativa primjenjuje se i u BiH kao dio procesa evropskih integracija, ali svijest građana o pravima na privatnost ostaje zabrinjavajuće niska.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"65px\"} -->\n<div style=\"height:65px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Digitalna nejednakost</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Brzi internet nije ravnomjerno dostupan u svim dijelovima BiH. Razlika između urbanih centara poput Sarajeva, Banja Luke i Mostara i manjih mjesta i sela i dalje je izražena - kako u brzini interneta, tako i u cijeni pristupa.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Govor mržnje online</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Etničke i političke podjele koje postoje u fizičkom prostoru direktno se prenose na digitalni. Istraživanja pokazuju da je BiH jedna od zemalja regije s najvećim udjelom govora mržnje na društvenim mrežama, posebno u periodima izbora i kriza.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">E-uprava i digitalne javne usluge</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Digitalizacija državnih usluga napreduje sporije nego u susjednim zemljama. Građani još uvijek moraju fizički dolaziti po mnoge dokumente i potvrde. Ipak, neke opštine i institucije uvode online usluge, što je korak u pravom smjeru.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->', 'BiH kontekst', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2026-06-03 17:42:30', '2026-06-03 17:42:30', '', 16, 'http://localhost/mywordpress/?p=174', 0, 'revision', '', 0),
(175, 1, '2026-06-03 17:46:48', '2026-06-03 17:46:48', '<!-- wp:paragraph {\"align\":\"wide\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center alignwide\"><em>Ovaj sajt nastao je kao školski projekat na temu onlajn komunikacije i njenog uticaja na društvo. Cilj mi je bio da na jednom mjestu prikupim podatke, statistike i zanimljivosti o tome kako internet i društvene mreže mijenjaju naš svakodnevni život.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>Zašto je odabrana ova tema</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\",\"verticalAlignment\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-contrast-2-color\">Tema onlajn komunikacije odabrana je jer predstavlja svakodnevnu pojavu koju koristimo gotovo nesvjesno, a njen uticaj na društvo, međuljudske odnose i mentalno zdravlje često ostaje neistražen. Cilj je bio sagledati kako društvene mreže mijenjaju način komunikacije, održavanja prijateljstava i provođenja slobodnog vremena.</mark></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-contrast-2-color\">Posebno je zanimljiv lokalni kontekst - kako ova tema izgleda u Bosni i Hercegovini u poređenju sa globalnim trendovima.</mark></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\",\"left\":\"0\",\"right\":\"0\"},\"margin\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-columns alignwide\" style=\"margin-top:var(--wp--preset--spacing--40);margin-bottom:var(--wp--preset--spacing--40);padding-top:var(--wp--preset--spacing--20);padding-right:0;padding-bottom:var(--wp--preset--spacing--20);padding-left:0\"><!-- wp:column {\"style\":{\"color\":{\"gradient\":\"linear-gradient(180deg,rgb(181,189,188) 0%,rgb(249,249,249) 100%)\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|20\",\"right\":\"var:preset|spacing|20\"},\"blockGap\":\"var:preset|spacing|10\"},\"border\":{\"width\":\"0px\",\"style\":\"none\",\"radius\":{\"topLeft\":\"35px\",\"topRight\":\"35px\",\"bottomLeft\":\"35px\",\"bottomRight\":\"35px\"}}}} -->\n<div class=\"wp-block-column has-background\" style=\"border-style:none;border-width:0px;border-top-left-radius:35px;border-top-right-radius:35px;border-bottom-left-radius:35px;border-bottom-right-radius:35px;background:linear-gradient(180deg,rgb(181,189,188) 0%,rgb(249,249,249) 100%);padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--20);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--20)\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong>Cilj projekta</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Istražiti kako onlajn komunikacija utiče na društvo i prikazati podatke na zanimljiv i pristupačan način.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|20\",\"right\":\"var:preset|spacing|20\"},\"blockGap\":\"var:preset|spacing|10\"},\"border\":{\"radius\":{\"topLeft\":\"35px\",\"topRight\":\"35px\",\"bottomLeft\":\"35px\",\"bottomRight\":\"35px\"}}},\"gradient\":\"gradient-5\"} -->\n<div class=\"wp-block-column has-gradient-5-gradient-background has-background\" style=\"border-top-left-radius:35px;border-top-right-radius:35px;border-bottom-left-radius:35px;border-bottom-right-radius:35px;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--20);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--20)\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong>Metodologija</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Podaci su prikupljeni iz izvještaja DataReportal, Statista i We Are Social, uz vlastitu anketu provedenu među korisnicima.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong> Tehnologije korištene u projektu</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:table {\"className\":\"is-style-regular\",\"style\":{\"border\":{\"width\":\"3px\"}},\"gradient\":\"gradient-5\"} -->\n<figure class=\"wp-block-table is-style-regular\"><table class=\"has-gradient-5-gradient-background has-background has-fixed-layout\" style=\"border-width:3px\"><thead><tr><th class=\"has-text-align-left\" data-align=\"left\">Tehnologije</th><th class=\"has-text-align-left\" data-align=\"left\">Svrha</th></tr></thead><tbody><tr><td class=\"has-text-align-left\" data-align=\"left\">WordPress</td><td class=\"has-text-align-left\" data-align=\"left\">Izrada i hosting glavnog sajta</td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">GitHub Pages</td><td class=\"has-text-align-left\" data-align=\"left\">Hosting interaktivne ankete</td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Google Sheets</td><td class=\"has-text-align-left\" data-align=\"left\">Baza podataka za glasove</td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Google Apps Script</td><td class=\"has-text-align-left\" data-align=\"left\">Backend za primanje i slanje podataka</td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Chart.js</td><td class=\"has-text-align-left\" data-align=\"left\">Crtanje grafikona u realnom vremenu</td></tr></tbody></table></figure>\n<!-- /wp:table -->\n\n<!-- wp:separator {\"align\":\"wide\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}}}} -->\n<hr class=\"wp-block-separator alignwide has-alpha-channel-opacity\" style=\"margin-top:var(--wp--preset--spacing--30);margin-bottom:var(--wp--preset--spacing--30)\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>Literatura i izvori</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"className\":\"is-style-default\"} -->\n<ul class=\"wp-block-list is-style-default\"><!-- wp:list-item -->\n<li><em>DataReportal (2025). Digital 2025 Global Overview Report. <a href=\"https://datareportal.com\">https://datareportal.com</a></em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>We Are Social (2025). Global Digital Report 2025. <a href=\"https://wearesocial.com\">https://wearesocial.com</a></em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Statista (2025). Social Media Statistics. <a href=\"https://statista.com\">https://statista.com</a></em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Internet World Stats (2025). Bosnia and Herzegovina Internet Usage. <a href=\"https://internetworldstats.com\">https://internetworldstats.com</a></em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Pew Research Center (2024). Social Media Use in 2024. <a href=\"https://pewresearch.org\">https://pewresearch.org</a></em></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->', 'O projektu', '', 'inherit', 'closed', 'closed', '', '43-revision-v1', '', '', '2026-06-03 17:46:48', '2026-06-03 17:46:48', '', 43, 'http://localhost/mywordpress/?p=175', 0, 'revision', '', 0),
(176, 1, '2026-06-03 17:54:56', '2026-06-03 17:54:56', '<!-- wp:group {\"metadata\":{\"categories\":[\"text\"],\"patternName\":\"twentytwentyfour/text-alternating-images\",\"name\":\"Text with alternating images\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\"><!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"className\":\"is-style-asterisk\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center is-style-asterisk\"><strong>Društvene mreže kao novi javni prostor</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null},\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>U BiH digitalne platforme nisu samo zabava - one su postale mjesto vijesti,<br>politike, dijaspore i svakodnevne komunikacije.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null},\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"var:preset|spacing|40\"} -->\n<div style=\"height:var(--wp--preset--spacing--40)\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|60\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"40%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:40%\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\"} -->\n<h3 class=\"wp-block-heading is-style-default\"><strong>Facebook dominira</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"className\":\"is-style-checkmark-list\",\"style\":{\"typography\":{\"lineHeight\":\"1.75\"}}} -->\n<ul style=\"line-height:1.75\" class=\"wp-block-list is-style-checkmark-list\"><!-- wp:list-item -->\n<li><em>Najpopularnija platforma kod 25 - 45 godina</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Glavno mjesto javne rasprave i vijesti</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Ključni kanal za dijasporu</em></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:image {\"id\":84,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"is-style-rounded\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"300px\",\"topRight\":\"300px\",\"bottomLeft\":\"300px\",\"bottomRight\":\"300px\"}}}} -->\n<figure class=\"wp-block-image size-large has-custom-border is-style-rounded\"><img src=\"http://localhost/mywordpress/wp-content/uploads/2026/05/brett-jordan-eefrxcpixna-unsplash.jpg?w=1024\" alt=\"\" class=\"wp-image-84\" style=\"border-top-left-radius:300px;border-top-right-radius:300px;border-bottom-left-radius:300px;border-bottom-right-radius:300px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"var:preset|spacing|40\"} -->\n<div style=\"height:var(--wp--preset--spacing--40)\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|60\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"width\":\"50%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:image {\"id\":85,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"is-style-rounded\",\"style\":{\"border\":{\"radius\":{\"topLeft\":\"300px\",\"topRight\":\"300px\",\"bottomLeft\":\"300px\",\"bottomRight\":\"300px\"}}}} -->\n<figure class=\"wp-block-image size-large has-custom-border is-style-rounded\"><img src=\"http://localhost/mywordpress/wp-content/uploads/2026/05/collabstr-0vk7hejwlde-unsplash.jpg?w=1024\" alt=\"\" class=\"wp-image-85\" style=\"border-top-left-radius:300px;border-top-right-radius:300px;border-bottom-left-radius:300px;border-bottom-right-radius:300px\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"40%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:40%\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\"} -->\n<h3 class=\"wp-block-heading is-style-default\"><strong>TikTok i mladi</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"className\":\"is-style-checkmark-list\",\"style\":{\"typography\":{\"lineHeight\":\"1.75\"}}} -->\n<ul style=\"line-height:1.75\" class=\"wp-block-list is-style-checkmark-list\"><!-- wp:list-item -->\n<li><em>Najbrže rastuća platforma među korisnicima do 24 godine</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Novi format konzumiranja vijesti kroz kratke, viralne videe</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Lokalni kreatori sadržaja grade publiku i van granica BiH</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Platforme poput TikToka mijenjaju i jezik i kulturu mladih</em></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"categories\":[\"text\"],\"patternName\":\"twentytwentyfour/text-feature-grid-3-col\",\"name\":\"Feature grid, 3 columns\"},\"align\":\"full\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"}}},\"backgroundColor\":\"base-2\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-base-2-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--50);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"0px\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"className\":\"is-style-asterisk\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center is-style-asterisk\"><strong>Izazovi digitalnog društva</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"0px\",\"style\":{\"layout\":{\"flexSize\":\"0px\",\"selfStretch\":\"fixed\"}}} -->\n<div style=\"height:0px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Da li je BiH digitalno napredna zemlja - ili samo izgleda tako na papiru?</p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"29px\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div style=\"margin-top:0;margin-bottom:0;height:29px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Dezinformacije i lažne vijesti</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Bosanskohercegovački online prostor posebno je ranjiv na dezinformacije zbog fragmentiranog medijskog tržišta, etničkih podjela i slabe medijske regulacije. Lažne vijesti šire se najčešće putem Facebook grupa i WhatsApp poruka, često bez ikakve provjere izvora.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Digitalna pismenost</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Starije generacije i stanovnici ruralnih područja suočavaju se sa značajnim preprekama u korištenju digitalnih usluga. Osnovna pismenost nije dovoljna - potrebno je razumjeti kako funkcionišu algoritmi, prepoznati lažne vijesti i zaštititi svoje podatke.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Zaštita privatnosti</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Većina korisnika u BiH nije svjesna koliko podataka dijeli sa platformama svakodnevno. GDPR regulativa primjenjuje se i u BiH kao dio procesa evropskih integracija, ali svijest građana o pravima na privatnost ostaje zabrinjavajuće niska.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"65px\"} -->\n<div style=\"height:65px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Digitalna nejednakost</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Brzi internet nije ravnomjerno dostupan u svim dijelovima BiH. Razlika između urbanih centara poput Sarajeva, Banja Luke i Mostara i manjih mjesta i sela i dalje je izražena - kako u brzini interneta, tako i u cijeni pristupa.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">Govor mržnje online</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Etničke i političke podjele koje postoje u fizičkom prostoru direktno se prenose na digitalni. Istraživanja pokazuju da je BiH jedna od zemalja regije s najvećim udjelom govora mržnje na društvenim mrežama, posebno u periodima izbora i kriza.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|10\"}}} -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3,\"className\":\"is-style-default\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\",\"textAlign\":\"left\"}},\"fontSize\":\"medium\",\"fontFamily\":\"body\"} -->\n<h3 class=\"wp-block-heading has-text-align-left is-style-default has-body-font-family has-medium-font-size\" style=\"font-style:normal;font-weight:600\">E-uprava i digitalne javne usluge</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\"><em>Digitalizacija državnih usluga napreduje sporije nego u susjednim zemljama. Građani još uvijek moraju fizički dolaziti po mnoge dokumente i potvrde. Ipak, neke opštine i institucije uvode online usluge, što je korak u pravom smjeru.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"></blockquote>\n<!-- /wp:quote --></div>\n<!-- /wp:group -->', 'BiH kontekst', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2026-06-03 17:54:56', '2026-06-03 17:54:56', '', 16, 'http://localhost/mywordpress/?p=176', 0, 'revision', '', 0),
(177, 1, '2026-06-03 17:57:52', '2026-06-03 17:57:52', '<!-- wp:paragraph {\"align\":\"wide\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center alignwide\"><em>Ovaj sajt nastao je kao projekat na temu onlajn komunikacije i njenog uticaja na društvo. Cilj je bio da se na jednom mjestu prikupe podaco, statistike i zanimljivosti o tome kako internet i društvene mreže mijenjaju naš svakodnevni život.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>Zašto je odabrana ova tema</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\",\"verticalAlignment\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-contrast-2-color\">Tema onlajn komunikacije odabrana je jer predstavlja svakodnevnu pojavu koju koristimo gotovo nesvjesno, a njen uticaj na društvo, međuljudske odnose i mentalno zdravlje često ostaje neistražen. Cilj je bio sagledati kako društvene mreže mijenjaju način komunikacije, održavanja prijateljstava i provođenja slobodnog vremena.</mark></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><mark style=\"background-color:rgba(0, 0, 0, 0)\" class=\"has-inline-color has-contrast-2-color\">Posebno je zanimljiv lokalni kontekst - kako ova tema izgleda u Bosni i Hercegovini u poređenju sa globalnim trendovima.</mark></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\",\"left\":\"0\",\"right\":\"0\"},\"margin\":{\"top\":\"var:preset|spacing|40\",\"bottom\":\"var:preset|spacing|40\"}}}} -->\n<div class=\"wp-block-columns alignwide\" style=\"margin-top:var(--wp--preset--spacing--40);margin-bottom:var(--wp--preset--spacing--40);padding-top:var(--wp--preset--spacing--20);padding-right:0;padding-bottom:var(--wp--preset--spacing--20);padding-left:0\"><!-- wp:column {\"style\":{\"color\":{\"gradient\":\"linear-gradient(180deg,rgb(181,189,188) 0%,rgb(249,249,249) 100%)\"},\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|20\",\"right\":\"var:preset|spacing|20\"},\"blockGap\":\"var:preset|spacing|10\"},\"border\":{\"width\":\"0px\",\"style\":\"none\",\"radius\":{\"topLeft\":\"35px\",\"topRight\":\"35px\",\"bottomLeft\":\"35px\",\"bottomRight\":\"35px\"}}}} -->\n<div class=\"wp-block-column has-background\" style=\"border-style:none;border-width:0px;border-top-left-radius:35px;border-top-right-radius:35px;border-bottom-left-radius:35px;border-bottom-right-radius:35px;background:linear-gradient(180deg,rgb(181,189,188) 0%,rgb(249,249,249) 100%);padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--20);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--20)\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong>Cilj projekta</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Istražiti kako onlajn komunikacija utiče na društvo i prikazati podatke na zanimljiv i pristupačan način.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|20\",\"right\":\"var:preset|spacing|20\"},\"blockGap\":\"var:preset|spacing|10\"},\"border\":{\"radius\":{\"topLeft\":\"35px\",\"topRight\":\"35px\",\"bottomLeft\":\"35px\",\"bottomRight\":\"35px\"}}},\"gradient\":\"gradient-5\"} -->\n<div class=\"wp-block-column has-gradient-5-gradient-background has-background\" style=\"border-top-left-radius:35px;border-top-right-radius:35px;border-bottom-left-radius:35px;border-bottom-right-radius:35px;padding-top:var(--wp--preset--spacing--30);padding-right:var(--wp--preset--spacing--20);padding-bottom:var(--wp--preset--spacing--30);padding-left:var(--wp--preset--spacing--20)\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\"><strong>Metodologija</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\"><em>Podaci su prikupljeni iz izvještaja DataReportal, Statista i We Are Social, uz vlastitu anketu provedenu među korisnicima.</em></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong> Tehnologije korištene u projektu</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:table {\"className\":\"is-style-regular\",\"style\":{\"border\":{\"width\":\"3px\"}},\"gradient\":\"gradient-5\"} -->\n<figure class=\"wp-block-table is-style-regular\"><table class=\"has-gradient-5-gradient-background has-background has-fixed-layout\" style=\"border-width:3px\"><thead><tr><th class=\"has-text-align-left\" data-align=\"left\">Tehnologije</th><th class=\"has-text-align-left\" data-align=\"left\">Svrha</th></tr></thead><tbody><tr><td class=\"has-text-align-left\" data-align=\"left\">WordPress</td><td class=\"has-text-align-left\" data-align=\"left\">Izrada i hosting glavnog sajta</td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">GitHub Pages</td><td class=\"has-text-align-left\" data-align=\"left\">Hosting interaktivne ankete</td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Google Sheets</td><td class=\"has-text-align-left\" data-align=\"left\">Baza podataka za glasove</td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Google Apps Script</td><td class=\"has-text-align-left\" data-align=\"left\">Backend za primanje i slanje podataka</td></tr><tr><td class=\"has-text-align-left\" data-align=\"left\">Chart.js</td><td class=\"has-text-align-left\" data-align=\"left\">Crtanje grafikona u realnom vremenu</td></tr></tbody></table></figure>\n<!-- /wp:table -->\n\n<!-- wp:separator {\"align\":\"wide\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\"}}}} -->\n<hr class=\"wp-block-separator alignwide has-alpha-channel-opacity\" style=\"margin-top:var(--wp--preset--spacing--30);margin-bottom:var(--wp--preset--spacing--30)\"/>\n<!-- /wp:separator -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>Literatura i izvori</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:list {\"className\":\"is-style-default\"} -->\n<ul class=\"wp-block-list is-style-default\"><!-- wp:list-item -->\n<li><em>DataReportal (2025). Digital 2025 Global Overview Report. <a href=\"https://datareportal.com\">https://datareportal.com</a></em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>We Are Social (2025). Global Digital Report 2025. <a href=\"https://wearesocial.com\">https://wearesocial.com</a></em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Statista (2025). Social Media Statistics. <a href=\"https://statista.com\">https://statista.com</a></em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Internet World Stats (2025). Bosnia and Herzegovina Internet Usage. <a href=\"https://internetworldstats.com\">https://internetworldstats.com</a></em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Pew Research Center (2024). Social Media Use in 2024. <a href=\"https://pewresearch.org\">https://pewresearch.org</a></em></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->', 'O projektu', '', 'inherit', 'closed', 'closed', '', '43-revision-v1', '', '', '2026-06-03 17:57:52', '2026-06-03 17:57:52', '', 43, 'http://localhost/mywordpress/?p=177', 0, 'revision', '', 0);
